const isP=()=>ME.type==='P';
const sk=id=>ME.skills.includes(id);
const age=()=>S.y-S.birth;
function owned(id){const v=S&&S.me===ME?S.me.items[id]:null;if(!v)return false;if(v===true)return true;return v>S.turn}
function itemBonus(k){if(!S||S.me!==ME)return 0;let b=0;for(const it of ITEMS)if(it.b&&it.b[k]&&owned(it.id)){if(it.id==='bat1'&&owned('bat2'))continue;b+=it.b[k]}return b}
function itemSum(key){let v=0;for(const it of ITEMS)if(it[key]&&owned(it.id))v+=it[key];return v}
