const PHYS=['spd','arm','pow','rng','velo','sta','stf'];
const capOf=k=>ME.lb&&ME.lb[k]?87.5:80;
function ceilAt(k){const a=S&&S.me===ME?age():16,g=gtOf();return capOf(k)-Math.max(0,a-g.dec)*(PHYS.includes(k)?1.6:.8)*g.dr}
