function primeM(){try{if(!S||S.stage!=='pro')return 1;const a=S.y-S.birth,gt=(ME&&ME.gt)||'평균형',w=PRIME_W[gt];if(!w)return 1;const P=ME.type==='P',A=gt==='꾸준형'?(P?.03:.02):(P?.05:.03);return 1+A*knot(a,w,[0,1,1,0])}catch(e){return 1}}
function pkW(v){const d=DV(v);return d<=40?0:d>=70?1:Math.pow((d-40)/30,2.2)}
function ars(f=E){const q=PITCHES.map(k=>f(k)).filter(v=>v>0).sort((a,b)=>b-a);const fb=Math.max(33,(q[0]||0)*.6);const g=i=>{const v=q[i];if(v==null)return fb;if(i===0)return v;return v>fb?fb+(v-fb)*pkW(v):v};return g(0)*.42+g(1)*.32+g(2)*.26+(q[3]?2*pkW(q[3]):0)}
const pSyn=(f=E)=>{const n=PITCHES.reduce((t,k)=>t+(f(k)>0?pkW(f(k)):0),0),pc=f('pcl')||45;return(pc-50)*.09*Math.max(.5,n/3)};
const stuffC=(f=E)=>f('velo')*.31+f('stf')*.32+ars(f)*.37+pSyn(f)+(sk('spin')?3:0);
const DEFW={C:[0,.35,.65],'1B':[.2,.75,.05],'2B':[.5,.35,.15],SS:[.45,.3,.25],'3B':[.25,.4,.35],LF:[.5,.17,.33],CF:[.65,.2,.15],RF:[.3,.2,.5]};
const defScore=(f=E)=>{const w=DEFW[ME.pos]||[.4,.35,.25];const vb=('vis' in ME.r)?(f('vis')-50)*.04:0;return f('rng')*w[0]+(f('fld')+vb)*w[1]+f('arm')*w[2]};
function ovrE(){
  if(isP()){const s=stuffC();return ME.pos==='SP'?s*.55+E('ctl')*.3+E('sta')*.15:s*.65+E('ctl')*.3+E('sta')*.05}
  const off=E('con')*.36+E('pow')*.3+E('eye')*.2+E('spd')*.14;
  const w={C:.4,SS:.38,CF:.33,'2B':.32,'3B':.28,RF:.22,LF:.18,'1B':.12}[ME.pos]*.6,adj=0; /* v713: 포지션 가산 제거 */
  return off*(1-w)+defScore()*w+adj}
const kmh=v=>(128+v*.42).toFixed(1);
const gcls=v=>v>=80.5?'g8':v>=70?'g7':v>=60?'g6':v>=50?'g5':v>=32?'g4':'g3';
const word=v=>v>=80?'괴물급':v>=68?'리그 탑급':v>=62?'수준급':v>=55?'주전급':v>=48?'벤치~주전급':v>=42?'벤치·2군급':v>=36?'유망주':'미완성';
const usd=m=>`$${(m*10000/1380/1e6).toFixed(1)}M`,moneyL=(m,lg)=>lg==='MLB'?`${usd(m)} (약 ${money(m)})`:money(m);
const money=m=>m>=1e8?`${(m/1e8).toFixed(m>=1e9?0:1).replace(/\.0$/,'')}조`:m>=10000?`${(m/10000).toFixed(m>=100000?0:1)}억`:`${Math.round(m).toLocaleString()}만원`;
const f3=(n,d)=>d?(n/d).toFixed(3).replace(/^0/,''):'.000';
const avg=b=>f3(b.H,b.AB),obp=b=>f3(b.H+b.BB,b.PA),slg=b=>f3(b.H+b.D+2*b.T+3*b.HR,b.AB);
const opsN=b=>b.PA&&b.AB?(b.H+b.BB)/b.PA+(b.H+b.D+2*b.T+3*b.HR)/b.AB:0;
const ops=b=>opsN(b).toFixed(3).replace(/^0/,'');
const eraN=p=>p.outs?p.R*27/p.outs:99;
const era=p=>p.outs?eraN(p).toFixed(2):'-.--';
const ip=o=>`${Math.floor(o/3)}.${o%3}`;
const blankB=()=>({G:0,PA:0,AB:0,H:0,D:0,T:0,HR:0,RBI:0,R:0,BB:0,K:0,SB:0,CS:0,E:0,GDP:0});
const blankP=()=>({G:0,GS:0,W:0,L:0,SV:0,HLD:0,outs:0,H:0,R:0,BB:0,K:0,HR:0,CG:0,SHO:0,NH:0});
const addTo=(a,b)=>{for(const k in b)if(typeof b[k]==='number')a[k]=(a[k]||0)+b[k]};
const PADJ={C:10.8,SS:9.0,'2B':2.2,CF:2.5,'3B':0.0,RF:-4.0,LF:-7.5,'1B':-12.5};
/* WAR 분리: oWAR = 타격 득점 + 대체선수 보정 / dWAR = 수비 득점 + 포지션 보정 (WAR = oWAR + dWAR) */
function bWARsplit(b,lv){if(!b||!b.PA)return{o:0,d:0};const s=b.H-b.D-b.T-b.HR,w=(.69*b.BB+.89*s+1.27*b.D+1.62*b.T+2.03*b.HR)/b.PA,raa=(w-.33)/1.2*b.PA,f=b.G/140;
  const dhc=!!b._dh,dr=dhc?0:cl((x=>x<0?x*1.25:x)((defScore()-(LV[lv]||51))*.45+(sk('glove')?2.7:0)+(sk('laser')?1.8:0)),-15,15)*f-b.E*.25,pa_=dhc?-13:(PADJ[ME.pos]||0);const mg=lv==='MLB'?1.08:1;return{o:(raa+20*b.PA/600)/10*mg,d:(dr+pa_*f)/10*mg}}
function bWAR(b,lv){if(!b.PA)return 0;const x=bWARsplit(b,lv);return x.o+x.d}
