    coach:mkName()+' 감독',rows:[],awards:[],ach:{},news:[],queue:[],report:null,pro:null,mil:{status:'none'},
    lg:{str:TEAMS.map(()=>rn(50,2.5)),w:TEAMS.map(()=>0),l:TEAMS.map(()=>0),prev:shuffle(TEAMS.map((t,i)=>i))},
