  const maxO=type==='SP'?27:type==='MR'?(R()<cl(.4+relQ()*2.5+(E('sta')-50)*.006+mlBon(),.08,.78)?(mlEl()&&R()<.15?ri(7,9):ri(4,6)):3):(S._multi?(mlEl()&&R()<.15?ri(7,9):ri(4,6)):3);
