    if(type!=='SP'&&(pc>lim+12||Rn>=4))break;
    const tired=(Math.max(0,pc-lim*.75)*.18+Math.max(0,pc-lim*.9)*.22)*cl(1.15-(DV(E('sta'))-50)*.006,.8,1.25),risp=b[1]||b[2],PM=pitMods(type),tto=PM.tto*Math.max(0,Math.floor(outs/3)+1-2);
    const k=PM.k*cl(.185+pv(st-tired-tto-PM.st)*.0036+pv(ctl)*.0012+(sk('kmach')?.025:0),.05,.42)*(1+1.0*hsP840);
    const bb=cl(.085-pv(ctl)*(pv(ctl)<0?.0025:.0021)+Math.max(0,60-DV(ctl))*.0007-(sk('pin')?.012:0)+tired*.002,.02,.2);
    let h=cl(.325-pv(stf-tired-tto*.8-PM.st)*.0018-pv(ctl)*.0009+tired*.003,.2,.42)*(type==='SP'?1:.972)*(1-.25*hsP840);
    if(risp)h=cl(h-(men-50)*.0012-(sk('heart')?.02:0)+(sk('chicken')?.025:0)-(sk('clutch')&&S.big?.02:0),.17,.45);
    const hrS=cl(.09-pv(stf)*.0014-pv(velo)*.00088,.02,.2)*PM.hr*(1+tto*.03)*(sk('gb')?.8:1)*(sk('hrprone')?1.3:1)*(1-.4*hsP840);
    const r=R(),sc=n=>{Rn+=n};
