var HRB0=.066,HRS1=.0075,HRS2=.0065,HRT=70,HRS3=.0042;function hrStat(){try{const v=k=>k in ME.r?eff(k):eff('pow');const mlb=S.stage==='pro'&&S.pro&&S.pro.league==='MLB';return mlb?v('pow')*.9+v('eye')*.04+v('vis')*.06:v('pow')*.95+v('eye')*.02+v('vis')*.03}catch(e){return eff('pow')}}
/* 주력 안타 보정: 70 기준 — 아래로 갈수록 서서히↓(70→35 약 −0.013), 위로 갈수록 서서히↑(90 약 +0.008, 최대 +0.01) (설명 노노) */
function spdHit(v){return v<70?-Math.pow((70-v)/35,1.3)*.013:Math.min(.01,Math.pow((v-70)/20,1.2)*.008)}
/* 홈런 파워 비례(비대칭): 파워 60 미만은 1.018^(파워−60)로 가파르게↓ · 60 이상은 1.003^(파워−60)로 조금만↑ (설명 노노) */
function hrPw(){try{const p=DV(eff('pow'));return p<60?Math.max(.55,Math.pow(1.018,p-60)):Math.min(1.06,Math.pow(1.003,p-60))}catch(e){return 1}}

/* v608: MVP — 포지션별 기준 (같은 포지션 안 비교 성격): WAR + OPS(포지션 기준 대비) 합산 지수 · 곡선 확률 · 수비 포지션은 타격 기준 낮게 · 규정 타석만 채우면 됨 */
const MVP_O0={MLB:{C:0.897,'1B':1.07,'2B':0.894,'3B':0.995,SS:0.983,LF:1.09,CF:0.815,RF:1.007,DH:1.04},KBO:{C:0.954,'1B':1.091,'2B':0.925,'3B':1.027,SS:0.947,LF:1.053,CF:0.96,RF:1.1,DH:1.11}};
const MVP_SH={C:-1.225,'1B':0.175,'2B':0.19,'3B':0.125,SS:0.135,LF:0.485,CF:-0.05,RF:0.115,DH:1.0};
function mvpM(w,b,lg){try{if(!b||!b.AB)return w;const ops=(b.H+(b.BB||0))/(b.AB+(b.BB||0))+(b.H+(b.D||0)+2*(b.T||0)+3*(b.HR||0))/b.AB,pos=ME.pos;return w+(lg==='KBO'?.155:-1.038)} /* v728: MVP = 시즌 WAR만 (포지션 무관), 기준값 재보정 */catch(e){return w}}

/* ===================== POSITION / ORDER / GROWTH TYPE ===================== */
const POSKEY={'1B':[['pow',.6],['fld',.4]],C:[['arm',.6],['fld',.4]],SS:[['rng',.6],['arm',.25],['fld',.15]],'2B':[['rng',.6],['fld',.3],['spd',.1]],CF:[['rng',.65],['spd',.35]],'3B':[['arm',.6],['fld',.4]],LF:[['arm',.6],['rng',.4]],RF:[['arm',.7],['rng',.3]]};
const POSKN={'1B':'파워 · 타구처리','C':'타구처리 · 어깨','SS':'수비범위','2B':'수비범위','CF':'수비범위 · 주력','3B':'어깨 · 타구처리','LF':'어깨','RF':'어깨'};
function posFit(){const pk=POSKEY[ME.pos];return pk?pk.reduce((a,[k,w])=>a+E(k)*w,0):ovrE()}
function selScore(){return isP()?ovrE():ovrE()*.6+posFit()*.4}
function batOrder(L){const c=E('con'),p=E('pow'),s=E('spd'),e=E('eye'),t=c*.36+p*.3+e*.2+s*.14-L;
  const prof={1:s*.45+e*.3+c*.25,2:c*.5+e*.3+s*.2,3:c*.5+p*.5,4:p*.75+c*.25,5:p*.6+c*.4,6:(c+p)/2,7:(c+s)/2,8:c*.6+e*.4,9:s*.5+c*.5};
  const cand=t>=5?[4,3,1,2,5]:t>=1?[1,2,5,3,6]:t>=-3?[6,2,7,5]:[7,8,9];let best=cand[0],bv=-1e9;cand.forEach((o,i)=>{const v=prof[o]-i*.6;if(v>bv){bv=v;best=o}});return best}
const GTYPE={
  /* 조숙형: 고교 때 훈련이 잘 됨 · 26세부터 성장이 살짝 더딤 (시작 능력치↑·멘탈↑는 buildMe 쪽) */
  '조숙형':{m:a=>knot(a,[16,18,20,23,26,29,32],[1.3,1.25,1.05,.98,.78,.67,.62]),dec:28,dr:1.2},
  '평균형':{m:a=>1,dec:30,dr:1},
  /* 만성형: 20세까지 더디다가 21세부터 확 오름 (시작 능력치↓) */
  '만성형':{m:a=>knot(a,[16,19,20.5,22,28,31,34],[.85,.88,1,1.65,1.6,1.35,1.15]),dec:33,dr:.9},
  /* 꾸준형: 급하게 안 크지만 늦게까지 성장 · 노쇠 느림 */
  '꾸준형':{m:a=>knot(a,[18,24,29,33],[.96,1.04,1.14,1.15]),dec:31,dr:.75}};
const gtOf=()=>GTYPE[(ME&&ME.gt)||'평균형']||GTYPE['평균형'];
const gtM=()=>gtOf().m(age());
const GTHINT={'조숙형':'일찍 완성되는 타입 같다. 지금 쌓아둔 게 평생 간다','평균형':'차근차근 크는 정석적인 타입이다','만성형':'아직 몸이 덜 여물었다. 20대 중반에 확 필 수 있는 늦게 피는 꽃','꾸준형':'급하게 크진 않지만 오래 버틸 몸이다'};

/* ===================== LEAGUE PLAYERS ===================== */
const LPN=[
 {b:['홍창귀','오지한','문보걍','박해문','오스턴'],sp:['임찬큐','치리너스'],cl:'유영칸',su:'김진썽'},
 {b:['양의치','김재한','정수반','양석한','캐이브'],sp:['곽반','잭러그'],cl:'김택윤',su:'이영허'},
 {b:['송성분','이주헝','최주한','김건휘','푸이구'],sp:['하영몬','알칸타리'],cl:'주승오',su:'원종헌'},
 {b:['최점','한유솜','박성헌','에레디우','최지혼'],sp:['김광헌','엔더선'],cl:'조병혀',su:'노경운'},
 {b:['강백오','허경문','장성오','로하수','김상서'],sp:['고영퓨','해이수스'],cl:'박영헌',su:'손동헌'},
 {b:['노시한','채은석','문현반','리베라투','심우존'],sp:['문동조','펀세'],cl:'김서헌',su:'한승헉'},
 {b:['구자옥','김영옹','강민오','디아쯔','이재헌'],sp:['원태엔','후라두'],cl:'김재운',su:'이호송'},
 {b:['김도용','최형오','나성봄','김선반','위즈딤'],sp:['양현중','네얼'],cl:'정해엉',su:'전상헌'},
 {b:['전준오','윤동휘','고승밍','레이예수','손호옹'],sp:['박세옹','감보이'],cl:'김원종',su:'정철완'},
 {b:['박민오','김주완','박건오','데이비선','권희둥'],sp:['구창묘','라일러'],cl:'류진옥',su:'김영귀'}];
const g6=()=>gauss();
function mkLP(t,n,kind,star){const s=star||0;
  if(kind==='B')return{n,t,k:'B',a:ri(23,34),con:cl(54+g6()*6+s,35,78),pow:cl(51+g6()*8+s,30,80),spd:cl(50+g6()*9,25,80),eye:cl(52+g6()*6+s*.5,30,78),s:blankB()};
  return{n,t,k:kind,a:ri(23,34),r:cl(56+g6()*5+s,40,78),s:blankP()}}
function initLP(){const L=[];LPN.forEach((T,t)=>{T.b.forEach((n,i)=>L.push(mkLP(t,n,'B',i===3?3:0)));T.sp.forEach((n,i)=>L.push(mkLP(t,n,'SP',i===1?3:0)));L.push(mkLP(t,T.cl,'CL'));L.push(mkLP(t,T.su,'SU'))});
  L.filter(p=>p.k==='B').forEach((p,i)=>p.o=(i%5)+1);return L}
function ensureLP(){if(!S.lp)S.lp=initLP();if(!S.lg.d)S.lg.d=TEAMS.map(()=>0);if(!S.lg.rec)S.lg.rec=TEAMS.map(()=>[])}
function lpYear(){ensureLP();S.lp.forEach(p=>{p.a++;const d=p.a<=27?rn(1,1.5):p.a<=31?rn(0,1.5):rn(-1.6,1.5);
  if(p.k==='B'){p.con=cl(p.con+d,30,80);p.pow=cl(p.pow+d,25,82);p.spd=cl(p.spd-s01((p.a-28)/3)+rn(0,1),20,80);p.eye=cl(p.eye+d*.6,30,80)}else p.r=cl(p.r+d,38,80);
  if(p.a>=36&&R()<(p.a-35)*.2){const nm=legendName(p.t,p.k),np=mkLP(p.t,nm||mkName(),p.k,nm?2:0);np.a=ri(20,23);np.o=p.o;if(nm)news(`${TEAMS[p.t].nick} 신인 ${nm} 1군 합류 — "어디서 많이 본 이름인데?"`);Object.assign(p,np)}
  p.s=p.k==='B'?blankB():blankP()})}
const pois=l=>{let L=Math.exp(-l),k=0,p=1;do{k++;p*=R()}while(p>L&&k<40);return k-1};
function lpSimB(p,n){const m=p.s,str=S.lg.str[p.t],om=[.75,.85,1.15,1.3,1.2,1,.95,.9,.85][(p.o||5)-1];
  for(let g=0;g<n;g++){if(R()>.93)continue;m.G++;const pa=4+(p.o<=3?1:0)*(R()<.5?1:0)+(R()<.25?1:0)-(p.o>=7&&R()<.3?1:0);
    for(let i=0;i<pa;i++){m.PA++;const bb=cl(.075+(p.eye-55)*.0022+.1*s01((p.eye-54)/12),.03,.22);if(R()<bb){m.BB++;if(R()<.3)m.R++;if(R()<cl((p.spd-50)*.01,0,.32)+.1*s01((p.spd-65)/12)){if(R()<.72)m.SB++;else m.CS++}continue}
      m.AB++;const h=cl(.258+(p.con-55)*.0045+(str-50)*.00045+.007*s01((p.con-60)/12),.17,.38);if(R()>h){if(R()<.22)m.K++;if(R()<.09*om)m.RBI+=R()<.5?1:0;continue}
      m.H++;const hr=cl(.1+(p.pow-55)*.0075,.02,.32)*pfOf(p.t)*1.05*(1-.12*s01((p.pow-65)/12)),r=R();
      if(r<hr){m.HR++;m.R++;m.RBI+=1+(R()<.42*om?1:0)+(R()<.12*om?1:0)}else if(r<hr+.19){m.D++;m.RBI+=R()<.32*om?1:0;if(R()<.5)m.R++}else if(r<hr+.2+cl((p.spd-50)*.0008,0,.03)){m.T++;m.RBI+=R()<.5*om?1:0;if(R()<.6)m.R++}
      else{m.RBI+=R()<.19*om?1:0;if(R()<cl((p.spd-48)*.016,0,.45)+.25*s01((p.spd-58)/14)){if(R()<.74)m.SB++;else m.CS++}if(R()<.4)m.R++}}}}
function lpSimP(p,n){const m=p.s,str=S.lg.str[p.t],era0=cl(4.4-(p.r-56)*.17,1.5,7)*(1+.14*s01((p.r-60)/10));
  if(p.k==='SP'){const st=Math.round(n/5+rn(0,.35));for(let i=0;i<st;i++){m.G++;m.GS++;const ip=cl(5.7+(p.r-56)*.06+rn(0,1.2),1.5,9),outs=Math.round(ip*3),er=pois(era0*ip/9);m.outs+=outs;m.R+=er;m.K+=pois(ip*(.82+(p.r-56)*.018));m.BB+=pois(ip*cl(.36-(p.r-56)*.006,.15,.6));m.H+=pois(ip*cl(.95-(p.r-56)*.014,.6,1.3));
    if(outs>=27){m.CG++;if(!er)m.SHO++}const wp=cl(.6+(str-50)*.0055-er*.09+(ip-5)*.04,.05,.92);if(ip>=5&&R()<wp)m.W++;else if(R()<cl(.18+er*.08-(str-50)*.0036,.05,.8))m.L++}}
  else{const apps=Math.round(n*(p.k==='CL'?.42:.46)*rn(1,.12));for(let i=0;i<apps;i++){m.G++;const outs=R()<.85?3:ri(1,5);m.outs+=outs;const er=pois(era0*.92*outs/27);m.R+=er;m.K+=pois(outs/3*(1+(p.r-56)*.02));m.BB+=pois(outs/3*.38);m.H+=pois(outs/3*cl(.9-(p.r-56)*.014,.55,1.3));
    const opp=R()<(p.k==='CL'?.6:.52)*(1+(str-50)*.0055);if(opp){if(!er||R()<.35){if(p.k==='CL')m.SV++;else m.HLD++}else if(R()<.4)m.L++}else if(R()<.08)m.W++}}}
function simLeague(g,ps){ensureLP();const n=GM.KBO[S.m],avgS=S.lg.str.reduce((a,b)=>a+b)/10,my=S.stage==='pro'&&S.pro.league==='KBO'?S.pro.team:-1;
  S.lg.str.forEach((s,i)=>{const p=.5+(s-avgS)*.014+(i===my?(g&&ONE.includes(S.role)?ps*.0018:0)+(S.rel.coach-50)*.0004+(S.rel.chem-50)*.0009:0);let w=0,d=0;
    for(let k=0;k<n;k++){const r=R();if(r<.015){d++;S.lg.rec[i].push('D')}else if(r<p){w++;S.lg.rec[i].push('W')}else S.lg.rec[i].push('L')}
    S.lg.rec[i]=S.lg.rec[i].slice(-20);S.lg.w[i]+=w;S.lg.d[i]+=d;S.lg.l[i]+=n-w-d});
  S.lp.forEach(p=>p.k==='B'?lpSimB(p,n):lpSimP(p,n))}
const standings=()=>TEAMS.map((t,i)=>({i,w:S.lg.w[i],l:S.lg.l[i],d:(S.lg.d||[])[i]||0})).sort((a,b)=>b.w/(b.w+b.l||1)-a.w/(a.w+a.l||1));
function streakOf(rec){if(!rec||!rec.length)return'-';const x=rec.filter(r=>r!=='D');if(!x.length)return'-';const l=x[x.length-1];let n=0;for(let i=x.length-1;i>=0&&x[i]===l;i--)n++;return`${n}${l==='W'?'승':'패'}`}
function last10(rec){const x=(rec||[]).slice(-10);const w=x.filter(r=>r==='W').length,d=x.filter(r=>r==='D').length;return x.length?`${w}승${d?d+'무':''}${x.length-w-d}패`:'-'}

/* ===== rankings ===== */
const RKB=[['avg','타율',b=>b.AB?b.H/b.AB:0,v=>f3v(v),1],['hr','홈런',b=>b.HR,v=>v,0],['rbi','타점',b=>b.RBI,v=>v,0],['h','안타',b=>b.H,v=>v,0],['r','득점',b=>b.R,v=>v,0],['sb','도루',b=>b.SB,v=>v,0],['ops','OPS',b=>opsN(b),v=>f3v(v),1],['obp','출루율',b=>b.PA?(b.H+b.BB)/b.PA:0,v=>f3v(v),1],['slg','장타율',b=>b.AB?(b.H+(b.D||0)+2*(b.T||0)+3*b.HR)/b.AB:0,v=>f3v(v),1]];
const RKP=[['era','평균자책',p=>p.outs?p.R*27/p.outs:99,v=>v.toFixed(2),1,true],['w','승리',p=>p.W,v=>v,0],['sv','세이브',p=>p.SV,v=>v,0],['hld','홀드',p=>p.HLD,v=>v,0],['k','탈삼진',p=>p.K,v=>v,0],['whip','WHIP',p=>p.outs?(p.H+p.BB)*3/p.outs:99,v=>v.toFixed(2),1,true],['ip','이닝',p=>p.outs,v=>ip(v),0]];
const f3v=v=>v>=1?v.toFixed(3):v.toFixed(3).replace(/^0/,'');
function myKBO(){if(!(S.stage==='pro'&&S.pro&&S.pro.league==='KBO'))return null;const r=S.rows.filter(x=>x.y===S.y&&x.lv==='KBO');if(!r.length)return null;const b=blankB(),p=blankP();r.forEach(x=>{addTo(b,x.b);addTo(p,x.p)});return{n:ME.name,t:S.pro.team,k:isP()?'P':'B',me:true,s:isP()?p:b}}
function ranking(cat,pit){ensureLP();const def=(pit?RKP:RKB).find(c=>c[0]===cat),tg=t=>(S.lg.w[t]+S.lg.l[t]+((S.lg.d||[])[t]||0))||1;
  let pool=S.lp.filter(p=>pit?p.k!=='B':p.k==='B').map(p=>({n:p.n,t:p.t,s:p.s}));const me=myKBO();if(me&&(me.k==='P')===!!pit)pool.push(me);
  if(def[4])pool=pool.filter(p=>pit?p.s.outs>=tg(p.t)*3:p.s.PA>=tg(p.t)*3.1);
  pool.forEach(p=>p.v=def[2](p.s));pool=pool.filter(p=>def[4]||p.v>0);pool.sort((a,b)=>def[5]?a.v-b.v:b.v-a.v);
  let rk=0,prev=null;pool.forEach((p,i)=>{if(prev===null||p.v!==prev)rk=i+1;p.rk=rk;prev=p.v});return{def,list:pool}}
function leaderVal(cat,pit){const r=ranking(cat,pit),o=r.list.filter(p=>!p.me);return o.length?o[0].v:null}

