randEvent=function(){S.evLog=S.evLog||[];const recent=new Set(S.evLog.slice(-14));const ok=e=>{try{return e.c()}catch(x){return false}};
  let pool=EV.filter(ok);const fresh=pool.filter(e=>{const t=(e._t=e._t||(()=>{try{return e.f().title}catch(x){return''}})());return!recent.has(t)});if(fresh.length)pool=fresh;if(!pool.length)return null;
  const ev=pick(pool).f();S.evLog.push(ev.title);if(S.evLog.length>40)S.evLog.shift();return ev};

