  if(x&&x.clinch&&x.win&&tone!=='ring')L.push('시리즈 따냈다 다음 라운드 가자!','이 기세 그대로 우승까지','업셋 각 보인다 ㄷㄷ','올라간다!!! 오늘 잠 다 잤다','다음 상대 누구든 자신 있다');
  if(x&&x.gGreat){L.push(`${nz}존 한국시리즈에서도 열렸다 ㄷㄷ`,'그 다이빙 캐치가 시리즈를 바꿨다','호수비 하나로 분위기 가져왔다','저 수비는 진짜 돈 주고 봐야 함','그 타구 잡는 거 보고 소름');if(x.ps!=='KS')L.splice(0,1)}
  if(x&&x.gErr){L.push('그 실책 하나가 너무 컸다','큰 경기에서 실책은 진짜 치명적','실책 장면 계속 생각난다 ㅠ','수비가 발목 잡았다');if(proYears()>=9&&!S.hist.rings)L.push('무관기운 오늘도 출근','큰 경기만 되면 이러네 무관 장인');else if(S.hist.rings)L.push('반지 있는 선수도 이런 날이 있지','우승 경험 있는 선수가 이러면 더 아프다')}
  if(tone==='psGoat'&&proYears()>=9&&!S.hist.rings&&S.pro&&S.pro.league==='KBO')L.push(...GWAN.down.slice(0,4),'가을만 되면 무관기운 스멀스멀','이래서 반지가 없는 거다');
