  const clutchGap=ry&&ry.pa>=40&&av>=.27&&ry.h/ry.pa<av-.07;if(!big&&!clutchGap)return[];/* v842s: 가을 통산 좋은 선수·정규시즌도 별로인 선수한텐 '스찌' X (스찌는 정규시즌 숫자는 좋은데 큰 경기에 없는 선수한테 쓰는 말) */if(big&&!clutchGap){if(av<.27)return[];try{if(typeof psCar840==='function'&&psCar840().strong)return[]}catch(e){}}
