const lastLgWAR=lg=>{const ys=[...new Set(S.rows.filter(r=>r.lv===lg).map(r=>r.y))].sort();const y=ys[ys.length-1];if(y==null)return null;return S.rows.filter(r=>r.y===y&&r.lv===lg).reduce((a,r)=>a+rowWAR(r),0)*WARK(lg)};
