  abroadOffers(o).filter(x=>!(x.arg.lg===p.league&&x.t.startsWith(p.tname))).slice(0,3).forEach(x=>ch.push(x));
  if(o>=46){const per=kboReturnPer(o,lw),teams=shuffle(TEAMS.map((t,i)=>i)).slice(0,per>=250000?3:1);teams.forEach(t=>{const yrs=age()<=33?4:age()<=36?3:age()<=39?(R()<.5?3:2):1,tot=Math.round(per*yrs*rn(1,.06)/10000)*10000;ch.push({t:`KBO 복귀: ${TEAMS[t].city} ${TEAMS[t].nick}`,s:`${yrs}년 최대 ${money(tot)}`,d:`계약금 ${money(tot*.4)} · 연봉 ${money(tot*.45/yrs)} · 옵션 ${money(tot*.15)} (WAR 1.5 이상)`,act:'fa',arg:{team:t,yrs,tot,ret:1}})})}
