  if(b[k])v+=b[k];if(b.big&&S.big&&b.big[k])v+=b.big[k];
  if(b.pal&&PITCHES.filter(x=>raw(x)>=45).length>=4){if(k==='pcl')v+=3.6;if(PITCHES.includes(k))v+=1.8}
