const _crHash=s=>{let h=0;for(const ch of String(s))h=(h*31+ch.charCodeAt(0))>>>0;return h};
const _crPal=[['#1e3a8a','#facc15'],['#7f1d1d','#f8fafc'],['#14532d','#fde68a'],['#312e81','#f472b6'],['#0f172a','#38bdf8'],['#78350f','#fef3c7'],['#4c1d95','#fbbf24'],['#134e4a','#f8fafc']];
function crestData(name,fb){const n=String(name||'');
  const hit=CREST.find(c=>c.k.some(k=>n===k||n.includes(k)));if(hit)return hit;
  // 학교·대학·군팀 등: 이름에서 오리지널 엠블럼 생성
  const h=_crHash(n),p=_crPal[h%_crPal.length],ini=n.replace(/[^가-힣A-Za-z]/g,'').slice(0,1)||'?';
  return{m:ini,c1:fb||p[0],c2:p[1],sh:['shield','round','hex'][h%3],ko:true}}
function crest(name,sz=20,fb){const d=crestData(name,fb),m=d.m,ln=m.length,fs=d.ko?17:ln>=3?11.5:ln===2?15:21,
  shp=d.sh==='round'?`<circle cx="20" cy="20" r="18" fill="${d.c1}" stroke="${d.c2}" stroke-width="2.6"/><circle cx="20" cy="20" r="13.6" fill="none" stroke="${d.c2}" stroke-width=".9" opacity=".55"/>`
   :d.sh==='hex'?`<path d="M20 2.2 35.6 11.1V28.9L20 37.8 4.4 28.9V11.1Z" fill="${d.c1}" stroke="${d.c2}" stroke-width="2.6" stroke-linejoin="round"/>`
   :`<path d="M20 2.4 35.4 7.4V19C35.4 28.6 28.8 34.6 20 37.8 11.2 34.6 4.6 28.6 4.6 19V7.4Z" fill="${d.c1}" stroke="${d.c2}" stroke-width="2.6" stroke-linejoin="round"/><path d="M8 11.5H32" stroke="${d.c2}" stroke-width="1" opacity=".5"/>`;
  return`<svg class="crest" width="${sz}" height="${sz}" viewBox="0 0 40 40" aria-hidden="true">${shp}<text x="20" y="${d.sh==='shield'?23.5:21}" text-anchor="middle" dominant-baseline="middle" fill="${d.c2}" font-family="${d.ko?"'Black Han Sans','Noto Sans KR',sans-serif":"'Barlow Condensed','Arial Narrow',sans-serif"}" font-weight="800" font-size="${fs}" letter-spacing="${ln>=3?'-.3':'0'}">${m}</text></svg>`}
function myTeamKey(){if(S.stage==='pro'&&S.pro)return S.pro.league==='KBO'?TEAMS[S.pro.team].nick:S.pro.tname;return teamLabel()}
