const LOOK={face:['둥근','갸름','각진'],hair:['짧은 머리','투블럭','장발','파마','삭발','스포츠','가르마','댄디','스파이크','올백','모히칸','울프컷','반삭'],hc:['흑발','갈색','금발','은발'],eye:['또렷','날카로운','웃는','졸린'],brow:['일자','진한','아치'],beard:['없음','콧수염','턱수염'],skin:['밝음','보통','구릿빛','짙음'],eb:['없음','아이블랙']};
const LOOKN={face:'얼굴형',hair:'헤어',hc:'머리색',eye:'눈',brow:'눈썹',beard:'수염',skin:'피부',eb:'아이블랙'};
const SKINC=['#f9dcc4','#efc39f','#d9a274','#b07a50'],HAIRC=['#1d1916','#5b3a22','#d9a441','#b9bcc4'];
const SKIN={밝음:SKINC[0],보통:SKINC[1],짙음:SKINC[3]};
function shade(hex,amt){const n=parseInt(hex.slice(1),16);let r=(n>>16)+amt,g=(n>>8&255)+amt,b=(n&255)+amt;r=cl(r,0,255);g=cl(g,0,255);b=cl(b,0,255);return'#'+((1<<24)+(r<<16)+(g<<8)+b).toString(16).slice(1)}
function lookOf(me){if(me.look)return me.look;let h=0;for(const c of me.name||'x')h=(h*31+c.charCodeAt(0))>>>0;const L={};Object.keys(LOOK).forEach((k,i)=>L[k]=(h>>(i*3))%LOOK[k].length);L.eb=0;L.skin=me.skin?Math.max(0,['밝음','보통','구릿빛','짙음'].indexOf(me.skin)):1;return L}
function randLook(){const L={};Object.keys(LOOK).forEach(k=>L[k]=ri(0,LOOK[k].length-1));L.eb=R()<.3?1:0;L.skin=ri(0,2);return L}
function gearOf(me){const has=id=>S&&S.me===me?owned(id):false;return{bat:has('bat2')?2:has('bat1')?1:0,glove:has('glove'),spike:has('spike')||has('shoe'),band:has('gym')||has('lab'),towel:has('trainer'),phones:false}}
const OL='#2a211c';
const limb=(d,c,w=8)=>`<path d="${d}" stroke="${OL}" stroke-width="${w+3}" stroke-linecap="round" fill="none"/><path d="${d}" stroke="${c}" stroke-width="${w}" stroke-linecap="round" fill="none"/>`;
