  feat:'<circle cx="60" cy="54" r="34" fill="#fff"/><path d="M36 34 Q60 54 36 76M84 34 Q60 54 84 76" stroke="#e23b3b" stroke-width="3" fill="none" stroke-dasharray="4 3"/><path d="M60 4 l6 14 15 2-11 10 3 15-13-8-13 8 3-15-11-10 15-2z" fill="url(#gld)" transform="translate(28 -2) scale(.5)"/>',
