function awardKind(n){return /월드시리즈 우승/.test(n)?'ws':/MVP|최우수/.test(n)?'mvp':/골든/.test(n)?'glove':/우승/.test(n)?'ring':/금메달|은메달|동메달|메달/.test(n)?'medal':/신인/.test(n)?'rookie':/왕|최다/.test(n)?'crown':/명예/.test(n)?'hof':'trophy'}
