  D.big.forEach(([v,l],i)=>{const sv=Number(v).toLocaleString();let fs=124;x.font=`800 ${fs}px ${FN}`;while(x.measureText(sv).width>270&&fs>60){fs-=4;x.font=`800 ${fs}px ${FN}`}T(sv,cols[i],900+dy,`800 ${fs}px ${FN}`,'#ffffff');T(l,cols[i],948+dy,`700 30px ${FB}`,MUT)});
  D.sub.forEach(([v,l],i)=>{T(String(v),cols[i],1030+dy,`700 64px ${FN}`,'#ffffff');T(l,cols[i],1070+dy,`500 27px ${FB}`,MUT)});
  /* 필 */
  x.font=`800 30px ${FB}`;let pw=D.pills.map(s=>x.measureText(s).width+56),tot=pw.reduce((a,b)=>a+b,0)+(pw.length-1)*18;const pk=Math.min(1,(W-80)/tot),pf=Math.round(30*pk);if(pk<1){x.font=`800 ${pf}px ${FB}`;pw=D.pills.map(s=>x.measureText(s).width+Math.round(56*pk));tot=pw.reduce((a,b)=>a+b,0)+(pw.length-1)*Math.round(18*pk)}let px0=W/2-tot/2;
  D.pills.forEach((s,i)=>{rr(px0,1112+dy,pw[i],62,31);x.fillStyle='rgba(244,196,48,.10)';x.fill();x.lineWidth=3;x.strokeStyle='#c99a1e';x.stroke();T(s,px0+pw[i]/2,1154+dy-(30-pf)/2,`800 ${pf}px ${FB}`,GOLD);px0+=pw[i]+Math.round(18*pk)});
