  tm.forEach((t,i)=>{const cx=W/2-tw/2+csp/2+i*csp;pxDraw(x,pxCrest(t.name),cx-9*cs,1206+dy,cs);T(`${t.n}시즌`,cx,1316+dy,`700 26px ${FB}`,'#a9b8d2')});
