/* ===================== 투수 보직별 능력 · 포스트시즌 휴식 규칙 · 성장 진로 · 매운 댓글 ===================== */
/* ---------- 보직별 중요 능력 ---------- */
function usableN(){const s=E('sta');return s<45?2:s<55?3:s<65?4:5}
function roleAdj(r){if(!isP())return 0;const v=eff('velo'),s=eff('stf'),c=eff('ctl'),pc=eff('pcl')||45,sta=E('sta');
  const q=PITCHES.map(k=>eff(k)).filter(x=>x>=40).sort((a,b)=>b-a);
  if(r==='SP'){const n=usableN(),u=q.slice(0,n),g=i=>u[i]??20,lim=g(0)*.5+g(1)*.3+g(2)*.2+(u.length>=4?2:0),arsPen=(lim-ars(eff))*.35;
    S._b2b=0;return arsPen+(u.length-3)*.9+(pc-55)*.07+(c-55)*.06+(sta-55)*.05-(v-55)*.05-(s-55)*.03}
  const b2b=S._b2b||0;return 3+(v-55)*.09+(s-55)*.07-(q.length-3)*.6-(pc-55)*.03-b2b*Math.max(0,68-sta)*.09+b2b*Math.max(0,sta-68)*.03}

/* ---------- 포스트시즌 등판 간격 ---------- */
function psPick(base,gn,g7,need){if(!isP()||!base||base==='none')return base||'none';const P=S._ps||(S._ps={day:0,last:-99,streak:0,lastDay:-99,started:0});
  P.day+=(gn===1?(P.started?2:0):1)+((gn===3||gn===6)&&need>=3?1:0);P.started=1;if(S._psDayNow!=null)P.day=S._psDayNow;const sta=E('sta');
  if(base==='SP'||base==='ace'){const rest=sta>=70?4:sta>=58?5:6;
    if(P.day-P.last-1>=rest){P.last=P.day;S._b2b=0;return base}
    if(g7&&P.day-P.last-1>=2&&sta>=55&&R()<.65){P.last=P.day;S._b2b=0;return'MR'}
    return'none'}
  if(['CL','SU','MR','RP','fP'].includes(base)){/* v857n: 불펜 연투 한도·등판 확률을 체력 곡선으로 (선발보다 낮은 체력에서 열림 · 조금만 올려도 효과) — 예전: 체력 68 넘으면 3연투 · 아니면 2연투 (계단) */const s1=x=>{x=Math.max(0,Math.min(1,x));return x*x*(3-2*x)},maxS=2+(R()<s1((sta-45)/20)?1:0)+(R()<.5*s1((sta-60)/20)?1:0),cons=P.lastDay===P.day-1?P.streak:0;if(cons>=maxS)return'none';
    if(g7||R()<cl((base==='CL'?.72:base==='SU'?.74:.66)+relQ()*1.5+.24*(s1((sta-40)/35)-.5),.35,.94)){P.streak=cons+1;P.lastDay=P.day;S._b2b=cons;return base}return'none'}
  return base}
{const _po=postseason;postseason=function(rep){S._ps=null;S._b2b=0;return _po(rep)}}
{const _mp=mlbPost;mlbPost=function(rep){S._ps=null;S._b2b=0;return _mp(rep)}}

