{const _ms4=monthStep;monthStep=function(rep){const inj0=ME.inj;_ms4(rep);try{const g=S.lastGame;
  if(g&&!ME.inj){let add=0;if(g.kind==='B')add+=g.m.G*.28;else add+=(g.m.G||0)*.47+(g.pc||0)*.0102;add*=cl(1-(ME.hid.dur-50)/120,.6,1.4);ME.fat=cl(ME.fat+add,0,100)}
  if(S.stage==='pro'||S.stage==='hs'){const r=S.rel,add=Math.max(0,45-r.chem)*.14+Math.max(0,38-r.coach)*.1;if(add>0)ME.fat=cl(ME.fat+add,0,100);if(add>=2.5)rep.lines.push('팀 분위기가 불편해서 쉬어도 쉰 것 같지 않다. (피로↑)')}
  if(!['off','pre','inj','army'].includes(S.role)&&!(S.phase===2&&S.m===10)&&(S.fevY!==S.y||(S.fevN||0)<2)&&R()<.056){if(S.fevY!==S.y){S.fevY=S.y;S.fevN=0}S.fevN++;const e=pickFev();if(!e)return;
    S.queue.push({title:`😮‍💨 ${e.t}`,text:e.x,ch:[{t:e.ok[0],s:fevS(e.ok[1]),act:'fev',arg:{f:e.ok[1],m:e.ok[2]}},{t:e.no[0],s:fevS(e.no[1]),act:'fev',arg:{f:e.no[1],m:e.no[2]}}]})}
  /* 부상 회복기간 */
  if(inj0&&!ME.inj&&(inj0.sev||1)>=2){const v=inj0.sev>=3?6:3;ME.rust={v,v0:v};rep.lines.push('복귀했지만 아직 경기 감각이 완전하지 않다. (부상 회복기간)')}
  else if(ME.rust&&!ME.inj){ME.rust.v-=rustRate();if(ME.rust.v<=0){ME.rust=null;rep.lines.push('부상 전 감각을 완전히 되찾았다!')}}}catch(e){}}}
function pickFev(){S.evY=S.evY||{};const L=FEV.filter(e=>!(isP()&&e.bat)&&!(!isP()&&e.pit)&&!(S.evY['😮‍💨 '+e.t]>=S.y-1));if(!L.length)return null;const e=pick(L);S.evY['😮‍💨 '+e.t]=S.y;return e}
const fevS=f=>[f.fat>0?`피로${f.fat>=16?'↑↑':'↑'}`:f.fat<0?`피로${f.fat<=-16?'↓↓':'↓'}`:'',f.chem>0?'팀 분위기↑':f.chem<0?'팀 분위기↓':'',f.coach>0?'감독 신뢰↑':f.coach<0?'감독 신뢰↓':'',f.fame>0?'인기↑':f.fame<0?'인기↓':''].filter(Boolean).join(' · ');
ACT.fev=function(a){const f=a.f;if(f.fat)ME.fat=cl(ME.fat+f.fat,0,100);for(const k of ['chem','coach','fame'])if(f[k])S.rel[k]=cl(S.rel[k]+f[k],0,100);return a.m};
