/* ---------- HD: 2배 해상도 + 얇은 외곽선 + 얼굴 디테일 ---------- */
function pxHD(g,me){const W=g.w*2,H=g.h*2,G=PG(W,H);for(let y=0;y<g.h;y++)for(let x=0;x<g.w;x++){const c=g.d[y*g.w+x];if(c){G.d[2*y*W+2*x]=c;G.d[2*y*W+2*x+1]=c;G.d[(2*y+1)*W+2*x]=c;G.d[(2*y+1)*W+2*x+1]=c}}
  const src=G.d.slice(),at=(x,y)=>x<0||y<0||x>=W||y>=H?null:src[y*W+x];
  for(let y=0;y<H;y++)for(let x=0;x<W;x++){if(src[y*W+x]!==PXOL)continue;const nb=[at(x-1,y),at(x+1,y),at(x,y-1),at(x,y+1)];if(nb.some(v=>!v))continue;const f=nb.find(v=>v&&v!==PXOL);if(f)G.d[y*W+x]=f}
  /* 둥근 모서리: 외곽선 계단 다듬기 */
  const s2=G.d.slice(),a2=(x,y)=>x<0||y<0||x>=W||y>=H?null:s2[y*W+x];
  for(let y=0;y<H;y++)for(let x=0;x<W;x++){if(s2[y*W+x]!==PXOL)continue;const e=[!a2(x-1,y),!a2(x+1,y),!a2(x,y-1),!a2(x,y+1)].filter(Boolean).length;if(e>=3)G.d[y*W+x]=null}
  if(!me.noFace)try{const L=lookOf(me),sk=(PX_SKIN[L.skin]||PX_SKIN[1])[0];
    /* 입: 얇은 미소 */const mouth=[[22,26],[23,26],[24,26],[25,26],[22,27],[23,27],[24,27],[25,27]];mouth.forEach(([x,y])=>{if(G.d[y*W+x]==='#9b3d3d')G.d[y*W+x]=sk});[[22,26],[25,26]].forEach(([x,y])=>pset(G,x,y,'#9b3d3d'));pset(G,23,27,'#9b3d3d');pset(G,24,27,'#9b3d3d');
    /* 눈 하이라이트 추가 (또렷) */if(L.eye===0){[[17,21],[31,21]].forEach(([x,y])=>pset(G,x,y,'#8f8ad8'))}
    /* 볼터치 작게 */[[12,24],[13,24],[12,25],[34,24],[35,25],[35,24]].forEach(([x,y])=>{const c=G.d[y*W+x];if(c&&/^#f/.test(c))G.d[y*W+x]=sk});
  }catch(e){}
  return G}
let pxPlayerBase=null;{const _pp=pxPlayer;pxPlayerBase=_pp;pxPlayer=function(me,o={}){return pxHD(_pp(me,o),me)}}
/* ---------- 픽셀 좋아요/싫어요 아이콘 ---------- */
const _ico={};
function pxIco(k){if(_ico[k])return _ico[k];const heart=['.HH.HH.','HHHHHHH','HHHHHHH','.HHHHH.','..HHH..','...H...'],down=['.......','HHHHHHH','.HHHHH.','..HHH..','...H...','.......'];
  const m=k[0]==='h'?heart:down,on=k.endsWith('on'),g=PG(7,6),col=on?(k[0]==='h'?'#f4c430':'#ff5b6b'):'#6f809c';
  m.forEach((r,y)=>[...r].forEach((c,x)=>{if(c==='H')pset(g,x,y,col)}));
  if(!on&&k[0]==='h'){const src=g.d.slice();for(let y=0;y<6;y++)for(let x=0;x<7;x++){if(!src[y*7+x])continue;const inner=[[x-1,y],[x+1,y],[x,y-1],[x,y+1]].every(([a,b])=>a>=0&&b>=0&&a<7&&b<6&&src[b*7+a]);if(inner)g.d[y*7+x]=null}}
  if(on&&k[0]==='h')pset(g,1,1,'#fff2a8');
  return _ico[k]=pxSVG(g,12,{cls:'px pxico'})}

