/* ---------- 경기: 타석 VS 컷인 + 대사창 ---------- */
function vsCut(g,e){const my=g.my,bat=e.half,fld=1-e.half,dF=crestData(g.ab[fld],g.c[fld]),dB=crestData(g.ab[bat],g.c[bat]),P=isP();
  const meG=pxAvatar(ME,198,{...myPxOpt(),cls:'px'}),opSeed=g.ab[P?bat:fld]+g.title+(e.inn||0),op=(()=>{const me={name:opSeed,body:'표준',type:P?'B':'P',look:null};me.look={...lookOf(me),eb:0,hair:(_h32(opSeed)>>>5)%13};const d=P?dB:dF;return pxAvatar(me,198,{c1:d.c1,c2:d.c2,num:(_h32(opSeed)%70)+1,cls:'px'})})();
  return`<div class="vscut" key="v${g.idx}"><div class="vs-bg"></div><div class="vs-l">${meG}<span class="vs-n">${esc(ME.name)}</span></div><div class="vs-vs">VS</div><div class="vs-r">${op}<span class="vs-n">${esc(g.ab[P?bat:fld])} ${P?'타자':'투수'}</span></div></div>`}
{const _vf=vFollow;vFollow=function(g){let h=_vf(g);try{const e=g.ev[Math.min(g.idx,g.ev.length-1)];if(g.idx>=g.ev.length-1)return h;
  const up=/meup/.test(e.c)||(isP()&&/마운드에 오른다|선발 투수/.test(e.t));
  if(up){h=h.replace(/<div class="fieldw">[\s\S]*?<\/svg><\/div>/,vsCut(g,e))}
  h=h.replace(/<div class="gprev">([\s\S]*?)<\/div>$/,(m,inner)=>{const items=inner.split('</div>').filter(s=>s.trim()).slice(0,2).map(s=>s+'</div>').join('');return`<div class="gprev">${items}</div>`});
  return h.replace('<div class="gnow','<div class="gnow pxbox')}catch(e){return h}}}

