const PT_W=64,PT_H=84,PT_OL='#2a1f2e';
function ptFill(g,fn,c){for(let y=0;y<PT_H;y++)for(let x=0;x<PT_W;x++)if(fn(x+.5,y+.5))g.d[y*PT_W+x]=c}
