function cmGameBad(t,x){if(!x||x.gPA==null&&x.ipO==null)return false;
  if(!isP()){const H=x.gH||0,OB=H+(x.gBB||0),HR=x.gHR||0;
    if(OB>0&&/무출루|출루 ?(한 번|를|도|조차)?.{0,3}못|출루가 없|한 번도 못 나|무안타|노히트/.test(t))return true;
    if(H>0&&/안타 (하나|한 개)(도|를)? ?못|방망이 실종|무안타|선풍기|첫 안타 기다/.test(t))return true;
    if(H>=2&&/침묵|차갑|조용했|한 건 없|밥값 못|존재감 없|안 보이/.test(t))return true;
    if(H===0&&/멀티히트|맹타|불방망이|안타 [2-5]개|[2-5]안타|타격감 미쳤/.test(t))return true;
    if(HR===0&&/(홈런|대포|아치|담장 넘|넘겨버|홈런포|멀티홈런)/.test(t)&&!/피홈런|홈런 기대|홈런 타자|홈런왕/.test(t))return true;
    if(OB>=2&&H<=1&&/역적|폭망|최악/.test(t))return true}
  else{const ra=x.ra||0,io=x.ipO||0;
    if(ra<=2&&io>=9&&/털렸|방화|불 지르|불지르|무너졌|배팅볼|난타/.test(t))return true;
    if(ra>=4&&/완벽|무실점|지워버|칼제구|철벽/.test(t))return true;if(io>=18&&/5회만 되면|숨차|5이닝 넘기|체력만 좀/.test(t))return true}
  return false}
/* 비슷한 댓글 묶음: 같은 주제는 시즌당 한 번 */
const CM_TOPIC=[/눈빛/,/가을 ?(사나이|남자|DNA|의 남자|전용)/,/큰 경기 (체질|울렁|약)/,/클러치/,/새가슴/,/울렁증/,/정규(시즌|리그)(용|에서만|은 몸풀기|엔 뭐|엔 조용)/,/스찌/,/무관(기운| 장인)/,/유관기운/,/혼자 야구/,/업고 (갔|간|가)/,/묻어가/,/이름 기억해/,/소름/,/심장 (쫄깃|터지|남아나)/,/피 말리/,/간첩/,/지배/,/리모컨/,/사랑한다/,/유니폼 (샀|산다|사러)/,/기죽지/,/고개 (들|숙이지)/,/믿고 (기다|본)/,/하이라이트/,/야알못/,/입꾹닫|까던 (놈|애)/,/직관 (승률|요정|갔)/,/에이스는 오늘도/,/MVP (줘|그냥|는 무조건)/,/클래스가 다/,/미쳤다 ?미쳤/,/이 맛에/,/눈물/,/레전드/];
const cmNorm=t=>String(t).replace(new RegExp((ME&&ME.name?[ME.name,giv(ME.name)]:[]).filter(Boolean).join('|')||'^$','g'),'').replace(/[\d\s.,!?~ㅋㅎㅠㅜ…'"“”·:()\-]/g,'').slice(0,12);
{const _c13=comments;comments=function(tone,x){let out=_c13(tone,x);try{if(!S||!ME)return out;
  /* 기록과 안 맞는 댓글 제거 */
  out=out.filter(c=>c.troll||!cmGameBad(c.t,x));out.forEach(c=>{if(c.re)c.re=c.re.filter(r=>!cmGameBad(r.t,x))});
  /* 포스트시즌: 시리즈 안 끝났으면 '시즌 끝' 류 제거 + 다음 경기 기대 */
  if(x&&(x.ps||x.intl)){if(!x.last)out=out.filter(c=>!SER_OVER.test(c.t));
    const ser=(x.title||'').match(/(\d)차전/),gno=ser?+ser[1]:0,gn=giv(ME.name),add=[];
    if(gno&&!x.last){const nx=gno+1;add.push(x.win!==false?pick([`${nx}차전이 기대된다`,`이 기세로 ${nx}차전도 가자`,`${nx}차전도 오늘처럼만`,`벌써 ${nx}차전 기다려짐`]):pick([`${nx}차전에서 갚아주자`,`아직 안 끝났다 ${nx}차전 보자`,`${nx}차전은 무조건 잡아야 됨`,`${nx}차전엔 ${gn} 살아나라`]))}
    if(x.elim&&!x.intl)add.push(pick(['올해 가을은 여기까지… 고생 많았다','그래도 여기까지 온 것만 해도 잘했다',`${gn} 내년 가을엔 꼭 반지 끼자`]));
    if(!isP()&&x.gPA>=3){const OB=(x.gH||0)+(x.gBB||0);if(OB===2&&(x.gHR||0)===0&&(x.gRBI||0)<2)add.push(pick([`2출루면 무난하게 할 몫은 했다`,`멀티출루 무난했다 ${gn}`,`화려하진 않아도 두 번 나갔으면 밥값 함`,`출루 두 번 이 정도면 충분히 제 역할`]))}
    add.filter(t=>!seenHas(t)).forEach((t,i)=>{seenAdd(t);out.splice(Math.min(out.length,2+i*2),0,{nk:pick(NICKS),fl:null,t,up:ri(60,380),dn:ri(0,8),nar:1,ago:pick(AGO),re:[]})})}
  /* 같은/비슷한 댓글은 1년에 한 번 */
  S.cmY=S.cmY||{};const y=S.y,keep=[],drop=[],usedT=new Set();
  for(const c of out){if(c.must){keep.push(c);continue}const k='n:'+cmNorm(c.t),tp=CM_TOPIC.findIndex(r=>r.test(c.t)),tk=tp>=0?'t:'+tp:null;
    const dup=S.cmY[k]===y||(tk&&(S.cmY[tk]===y||usedT.has(tk)));if(dup&&!c.troll){drop.push(c);continue}keep.push(c);if(tk)usedT.add(tk)}
  while(keep.length<3&&drop.length)keep.push(drop.shift());
  for(const c of keep){S.cmY['n:'+cmNorm(c.t)]=y;const tp=CM_TOPIC.findIndex(r=>r.test(c.t));if(tp>=0)S.cmY['t:'+tp]=y;(c.re||[]).forEach(r=>{})}
  /* 오래된 키 정리 */
  if(Object.keys(S.cmY).length>2500)for(const k in S.cmY)if(S.cmY[k]<y-1)delete S.cmY[k];
  return keep}catch(e){return out}}}

