  if(typeof MLBT!=='undefined')MLBT.forEach(t=>w.add(t[0]));if(typeof MLB_CITY!=='undefined')for(const k in MLB_CITY){w.add(k);w.add(MLB_CITY[k]);w.add(k+' '+MLB_CITY[k])}
