/* ===================== 잘하면 확실한 대우 — 실제 계약 사례 기준 ===================== */
/* 참고: 김도영 MVP 후 1억→5억(+400%) · 류현진 다저스 6년 $36M(포스팅)·토론토 4년 $80M·한화 8년 170억
   양의지 6년 152억 · 후안 소토 메츠 15년 $765M(연 $51M, 26세) · 오타니 다저스 10년 $700M(연 $70M, 29세) */
function lgWARs(lg,n){const ys=[...new Set(S.rows.filter(r=>r.lv===lg).map(r=>r.y))].sort((a,b)=>b-a).slice(0,n);return ys.map(y=>S.rows.filter(r=>r.y===y&&r.lv===lg).reduce((a,r)=>a+rowWAR(r),0))}
function wAvg(lg){const w=lgWARs(lg,3);if(!w.length)return 0;const wt=[.5,.3,.2].slice(0,w.length),s=wt.reduce((a,b)=>a+b,0);return w.reduce((a,v,i)=>a+Math.max(0,v)*wt[i],0)/s}
/* 1) MLB 검증된 선수: WAR당 약 $8.5M · 최고 연 $70M · 젊을수록 장기 계약 */
{const _mu=mlbUSD;mlbUSD=function(o,w,proven){if(!proven)return _mu(o,w,proven);const a=age(),wa=Math.max(wAvg('MLB'),Math.max(0,w)*.7);let u=1+wa*8.5;u*=knot(a,[26,29,33,36],[1.12,1,1,.8]);return Math.max(1000000/USDM/.93,cl(u,.78,70))}}
mlbYears=function(usd,proven){const a=age();if(a>=37)return 1;
  if(!proven){if(a<=26&&usd>=15)return 6;return usd>=20?ri(5,6):usd>=8?ri(3,4):ri(1,2)}
  if(usd>=35){if(a<=27)return ri(12,15);if(a<=29)return ri(10,12);if(a<=31)return ri(7,9);if(a<=33)return ri(4,6);return ri(2,3)}
  if(usd>=20){if(a<=29)return ri(6,8);if(a<=33)return ri(4,5);return 2}
  if(usd>=8){if(a<=33)return ri(2,4);return ri(1,2)}return 1};
/* 2) KBO FA: 37세 전까진 활약하면 제값 · 꾸준함 보너스 · 상한 연 30억 (양의지·최정급) */
faValue=function(o,w){const a=age(),aw=S.awards.filter(x=>x.y>=S.y-1),bonus=(aw.some(x=>x.n.includes('정규시즌 MVP'))?6:0)+aw.filter(x=>/왕|최다|골든/.test(x.n)).length*1.5,ww=lgWARs('KBO',3),steady=ww.length>=3&&ww.every(v=>v>=3)?1.15:1;
  const s=o+Math.max(-2,Math.max(w,wAvg('KBO')))*2+bonus;let v=(s>62?80000+(s-62)*11500:80000*Math.exp((s-62)*.1))*(1+S.rel.fame/250)*steady;
  v*=knot(a,[34,36,38],[1,1-.2*sg((3-w)/.5),.6]);return Math.min(v,300000)};
