  const sal=q.ch.find(c=>c.act==='sal');if(!sal)return r;const cur=S.pro.salary,a=age(),w=lastWAR(),yrs=proYears(),aw=S.awards.filter(x=>x.y===S.y).map(x=>x.n);
  const mvp=aw.some(n=>/정규시즌 MVP/.test(n)),roy=aw.some(n=>/신인왕/.test(n)),young=yrs<=3||a<=24;
