function trAdj(type,ctx,season){const o={hit:0,k:0,bb:0,hr:1,gap:0};for(const t of TR){if(t.t!==type||!ME.skills.includes(t.id))continue;let w;if(season){w=typeof t.f==='function'?t.f(ctx):t.f}else w=t.c_(ctx)?1:0;if(!w)continue;
  o.hit+=(t.a.hit||0)*w;o.k+=(t.a.k||0)*w;o.bb+=(t.a.bb||0)*w;o.gap+=(t.a.gap||0)*w;if(t.a.hr)o.hr*=1+(t.a.hr-1)*w}return o}
const OUTS=['GO','FO','LO'],HITS=['1B','2B','3B','HR'];
function trApplyBat(t,a){if(t==='K'&&a.k<0&&R()<-a.k/.2)t='GO';
  if(OUTS.includes(t)){if(a.bb>0&&R()<a.bb/.55)return'BB';if(a.hit>0&&R()<a.hit/.7)t='1B'}
  if(t==='1B'&&a.gap>0&&R()<a.gap)t='2B';if(['1B','2B','3B'].includes(t)&&a.hr>1&&R()<.12*(a.hr-1)/.88)t='HR';return t}
function trApplyPit(t,a){if(HITS.includes(t)&&a.hit<0&&R()<-a.hit/.25)t=t==='HR'?'FO':'GO';if(t==='HR'&&a.hr<1&&R()<1-a.hr)t='FO';if(t==='BB'&&a.bb<0&&R()<-a.bb/.08)t='GO';if(OUTS.includes(t)&&a.k>0&&R()<a.k/.5)t='K';return t}
