/* ===================== 주자 이동 애니메이션 · 희생플라이 · 트레이드 현실화 ===================== */
const BP=[[203,154],[150,101],[97,154],[150,212]],BH=[150,214];
function runAnim(g,e,draw){try{const L=e.last;if(!L||!L.pb||!e.b)return null;const prev={b:L.pb};const t=L.t,runs=L.runs||0;
  const reach=['1B','2B','3B','HR','BB'].includes(t);if(!reach&&!runs)return null;
  const src=[2,1,0].filter(i=>prev.b[i]);if(reach)src.push(-1);
  const dst=[];for(let k=0;k<runs;k++)dst.push(3);[2,1,0].filter(i=>e.b[i]).forEach(i=>dst.push(i));
  if(t==='BB'){/* 볼넷: 밀려나는 주자만 */}
  if(src.length!==dst.length)return null;
  const PER=.42;let out='',maxB=0;
  src.forEach((s,k)=>{const d=dst[k];const pts=[];let c=s;pts.push(c<0?BH:BP[c]);while(c<d){c++;pts.push(BP[c])}
    const [ex,ey]=d===3?BP[3]:BP[d];if(pts.length<2){if(d<3)out+=draw(ex,ey,s<0);return}
    const nb=pts.length-1,dur=nb*PER;maxB=Math.max(maxB,nb);
    const vals=pts.map(([x,y])=>`${x-ex} ${y-ey}`).join(';');
    const fade=d===3?`<animate attributeName="opacity" values="1;0" begin="${dur.toFixed(2)}s" dur=".25s" fill="freeze"/>`:'';
    out+=`<g><animateTransform attributeName="transform" type="translate" values="${vals}" dur="${dur.toFixed(2)}s" fill="freeze"/>${fade}${draw(ex,ey,s<0)}</g>`});
  const T=maxB*PER;S._runHold={idx:g.idx,ms:Math.round(T*1000),bat:src.includes(-1)};
  if(runs&&t!=='HR')out+=`<text x="150" y="196" text-anchor="middle" font-size="13" font-weight="900" fill="#ffe27a" opacity="0">+${runs} 득점!<animate attributeName="opacity" values="0;1" begin="${T.toFixed(2)}s" dur=".2s" fill="freeze"/></text>`;
  return out}catch(x){return null}}
/* 희생플라이: 3루 주자 있고 2아웃 전 뜬공이면 대부분 홈인 · 문구 표시 */
