function kboPedigree(){try{const kw=S.rows.filter(r=>r.lv==='KBO').reduce((a,r)=>a+rowWAR(r),0),mvp=S.awards.some(a=>/KBO.*MVP|정규시즌 MVP|최우수선수/.test(a.n)&&!/대회|고교/.test(a.n)),gg=S.awards.filter(a=>/골든글러브/.test(a.n)).length;return kw>=25||mvp||gg>=4?2:kw>=12||gg>=2?1:0}catch(e){return 0}}
