/* ===================== NEWS ===================== */
function artCard(a,i){const top=a.cm[0];return`<button class="art artbtn" data-act="art" data-i="${i}"><div class="row tiny muted"><span class="press">${a.press}</span><span>${a.y} ${PHASE[a.ph]}</span></div><h3>${esc(a.head)}</h3><p class="small muted">${esc(a.body)}</p>
  ${top?`<div class="topcm"><span class="cmav sm" style="background:${avc(String(top.nk).replace(/^@/,''))}">${esc(String(top.nk).replace(/^@/,'')[0])}</span><span class="small">${esc(top.t)}</span><span class="tiny muted" style="margin-left:auto">♥ ${kfmt(top.up)}</span></div>`:''}<div class="tiny muted">조회 ${(a.views||0).toLocaleString()} · 댓글 ${a.cm.length+a.cm.reduce((s,c)=>s+(c.re?c.re.length:0),0)} ›</div></button>`}
const kfmt=n=>n>=1000?(n/1000).toFixed(n>=10000?0:1)+'k':String(n);
const avc=s=>{let h=0;for(const ch of s)h=(h*31+ch.charCodeAt(0))>>>0;return['#3182f6','#f04452','#03b26c','#fe9800','#7c4dff','#14b8a6','#e05a9a','#64748b'][h%8]};
function cmHtml(c,j){const nk=String(c.nk).replace(/^@/,'');return`<div class="cm"><span class="cmav" style="background:${avc(nk)}">${esc(nk[0])}</span><div class="cmb">
  <div class="cmh"><b>${esc(c.nk)}</b>${c.fl?`<span class="flair">${esc(c.fl)}</span>`:''}<span class="ago">${c.ago||''}</span></div><div class="cmt">${esc(nmFull(c.t))}</div>
  <div class="cmf"><span class="lk">♥ ${kfmt(c.up)}</span>${(c.re||[]).length?`<span>답글 ${c.re.length}</span>`:''}${j===0&&c.up>=10?'<span class="hot">인기 댓글</span>':''}</div>
  ${(c.re||[]).map(r=>{const rn=String(r.nk).replace(/^@/,'');return`<div class="reply"><span class="cmav sm" style="background:${avc(rn)}">${esc(rn[0])}</span><div><b>${esc(r.nk)}</b> <span>${esc(nmFull(r.t))}</span></div></div>`}).join('')}</div></div>`}
function vNews(){let h=header();
  if(!S.arts.length)h+=`<div class="card"><span class="small muted">아직 당신에 대한 기사가 없어요. 활약하면 기자들이 찾아와요.</span></div>`;
  h+=S.arts.slice(0,20).map((a,i)=>artCard(a,i)).join('');
  h+=`<div class="card"><span class="lbl">타임라인</span><div class="feed">${S.news.slice(0,30).map(n=>`<div><span class="num muted tiny">${n.y} ${PHASE[n.ph]??''}</span> ${esc(n.t)}</div>`).join('')}</div></div>`;
  return h}
function vArticle(a){return`<div class="scrim" data-act="artclose"><div class="sheet artsheet" role="dialog" aria-modal="true" data-stop="1"><div class="grab"></div>
  <div class="row tiny muted"><span class="press">${a.press}</span><span class="sp"></span><span>${a.y} ${PHASE[a.ph]} · 조회 ${(a.views||0).toLocaleString()}</span></div><h2>${esc(a.head)}</h2><p>${esc(a.body)}</p>
  <div class="cmhead">댓글 ${a.cm.length+a.cm.reduce((s,c)=>s+(c.re?c.re.length:0),0)} <span class="tiny muted">· 추천순</span></div>${a.cm.map(cmHtml).join('')}
  <button class="btn" data-act="artclose">닫기</button></div></div>`}

/* ===================== CONTRACT ===================== */
const jersey=(c,name,num)=>`<svg class="jersey" viewBox="0 0 200 210" role="img" aria-label="${esc(name)} 등번호 ${num} 유니폼"><path d="M62 8 L30 22 L4 72 L36 88 L46 66 L46 202 L154 202 L154 66 L164 88 L196 72 L170 22 L138 8 Q100 26 62 8Z" fill="${c}" stroke="rgba(0,0,0,.18)" stroke-width="2"/><path d="M62 8 Q100 26 138 8" fill="none" stroke="rgba(255,255,255,.55)" stroke-width="4"/><text x="100" y="74" text-anchor="middle" font-size="19" font-weight="800" fill="#fff" font-family="var(--fb)">${esc(name)}</text><text x="100" y="168" text-anchor="middle" font-size="78" font-weight="800" fill="#fff" font-family="var(--fb)">${num}</text></svg>`;
function vContract(q){const c=q.c;
  if(q.step===1){const a=S.arts[0];
    return`<div class="ceremony"><div class="flash"></div><span class="ey">${c.kind==='draft'||c.kind==='dev'?'입단식':c.kind==='abroad'||c.kind==='minor'?'해외 진출 기자회견':'계약 기자회견'}</span>
    <h1>${c.kind==='fa'?`${c.years}년 총액 ${money(c.total)}<br>도장 쾅!`:c.kind==='abroad'?`${esc(c.tname)}<br>입단 확정!`:`${esc(c.tname)}<br>입단을 환영합니다`}</h1>
    <div class="cerrow">${jersey(c.color,ME.name,c.num)}</div><p class="quote">${esc(ME.name)} ${c.quote}</p>
    ${a?`<div class="card left"><div class="tiny muted">실시간 반응 · ${a.press}</div>${a.cm.slice(0,3).map(cmHtml).join('')}</div>`:''}</div>`}
  const rows=[['계약 형태',c.title.includes('CONTRACT')||c.title.includes('契約')?c.title:c.title.replace(' 계약서','').replace('계약서','계약')],['구단',c.tname],['선수',`${ME.name} (${POS[ME.pos]}, ${age()}세)`],
    ...(c.years?[['계약 기간',`${c.years}년 (${S.y+1}~${S.y+c.years} 시즌)`]]:[['계약 기간','구단 보류 기간']]),
    ...(c.total?[['총액',c.title.includes('MAJOR')?moneyL(c.total,'MLB'):money(c.total)]]:[]),['계약금',c.bonus?money(c.bonus):'없음'],['연봉',c.title.includes('MAJOR')?moneyL(c.salary,'MLB'):money(c.salary)],['비고',c.note||'-']];
  return`<div class="paper"><div class="row">${crest(c.tname,46,c.color)}<div class="sp"><div class="ptitle">${esc(c.title)}</div><div class="tiny muted">${c.no} · ${c.date}</div></div></div>
    <p class="small">${esc(c.tname)}(이하 "구단")와 ${esc(ME.name)}(이하 "선수")는 아래 조건으로 선수 계약을 체결하며, 선수는 리그 규약과 구단 규정을 성실히 준수한다.</p>
    <dl class="terms">${rows.map(([k,v])=>`<dt>${k}</dt><dd>${esc(v)}</dd>`).join('')}</dl>
    <div><div class="lbl" style="margin-bottom:8px">등번호 선택</div><div class="row wrap">${c.nums.map(n=>`<button class="chip ${c.num===n?'on':''}" data-act="cnum" data-v="${n}">${n}번</button>`).join('')}</div></div>
    <div><div class="row"><span class="lbl sp">선수 서명</span><button class="ibtn" data-act="csigclr">지우기</button><button class="ibtn on" data-act="csigauto">간편 서명</button></div>
    <div class="sigbox"><canvas id="sig" aria-label="서명란. 손가락으로 이름을 써주세요"></canvas>${c.signed?'':'<span class="sigph">여기에 손가락으로 서명하세요</span>'}</div></div>
    <div class="row small"><span class="sp muted">구단 대표이사</span><span class="stamp" style="border-color:${c.color};color:${c.color}">${esc(c.tname.split(' ').pop())}<br>직인</span></div></div>`}
function setupSig(){const cv=document.getElementById('sig'),q=nextQ();if(!cv||!q||q.type!=='contract')return;const c=q.c,dpr=window.devicePixelRatio||1,w=cv.clientWidth,h=cv.clientHeight;
  cv.width=w*dpr;cv.height=h*dpr;const x=cv.getContext('2d');x.scale(dpr,dpr);x.lineCap='round';x.lineJoin='round';x.lineWidth=3.4;x.strokeStyle='#0b1a4a';x.shadowColor='rgba(11,26,74,.25)';x.shadowBlur=.6;
  const draw=()=>{x.clearRect(0,0,w,h);if(c.auto){x.font=`italic 800 38px 'Brush Script MT','Snell Roundhand',cursive,sans-serif`;x.fillStyle=x.strokeStyle;x.textAlign='center';x.fillText(ME.name,w/2,h/2+12)}
    c.sig.forEach(s=>{x.beginPath();s.forEach(([px,py],i)=>{const X=px*w,Y=py*h;i?x.lineTo(X,Y):x.moveTo(X,Y)});x.stroke()})};draw();
  let cur=null;const pos=e=>{const r=cv.getBoundingClientRect();return[(e.clientX-r.left)/w,(e.clientY-r.top)/h]};
  cv.onpointerdown=e=>{e.preventDefault();cv.setPointerCapture(e.pointerId);cur=[pos(e)];c.sig.push(cur);const ph=cv.parentNode.querySelector('.sigph');if(ph)ph.remove()};
  cv.onpointermove=e=>{if(!cur)return;cur.push(pos(e));draw()};
  cv.onpointerup=cv.onpointercancel=()=>{if(!cur)return;cur=null;const pts=c.sig.reduce((s,a)=>s+a.length,0);if(pts>12&&!c.signed){c.signed=true;AU.sfx('pen');document.getElementById('abar').innerHTML=vBar()}save()}}

/* ===================== SHOP ===================== */
function vShop(){let h=header();
  h+=`<div class="card"><div class="row"><span class="lbl sp">보유 자금</span><b class="num">${money(S.money)}</b></div><div class="small muted">학생 땐 용돈, 프로가 되면 연봉이 매달 들어와요. 장비는 능력치에 바로 더해지고, 관리 서비스는 1년 단위이고 자동 갱신돼요.</div></div>`;
  const chainHas=it=>{let x=ITEMS.find(y=>y.rep===it.id);while(x){if(owned(x.id))return true;x=ITEMS.find(y=>y.rep===x.id)}return false};
  const lifeL=ITEMS.filter(it=>it.cat==='life'&&!chainHas(it));
  h+=`<div class="card" style="gap:0"><div class="row" style="padding-bottom:6px"><span class="lbl sp">🏠 생활</span><span class="tiny" style="color:#d4a017">생활 만족도 <b>${lifePct()}%</b></span></div><div class="tiny muted" style="padding-bottom:6px">새로 산 건 만족도가 확 오르고 5년에 걸쳐 서서히 익숙해져요. 비쌀수록 크게 올라요.</div>${lifeL.map(it=>{const has=owned(it.id),can=S.money>=it.p&&!has,until=S.me.items[it.id]&&S.me.items[it.id]!==true?S.me.items[it.id]-S.turn:0;
    return`<div class="row" style="padding:10px 0;border-bottom:1px solid var(--line)"><div class="sp"><div style="font-weight:700;font-size:.9rem">${it.n}</div><div class="tiny muted">${it.d}${until>0?` · ${until}턴 남음`:''}</div></div>${has?'<span class="chip up">보유</span>':`<button class="btn sm ${can?'pri':''}" data-act="buy" data-k="${it.id}" ${can?'':'disabled'}>${money(it.p)}</button>`}</div>`}).join('')}</div>`;
  if(S.stage==='pro'){const lc=livingCost(),at=autoTotal(),inc=S.pro.salary/12;h=h.replace('<!--LEDGER-->','');
    h+=`<div class="card"><div class="row"><span class="lbl sp">📒 가계부</span><span class="tiny muted">매달 자동 정산</span></div>
      <div class="ledg"><div><span>월 수입</span><b class="up">+${money(inc)}</b></div><div><span>월 생활비</span><b class="dn">−${money(lc)}</b></div><div><span>관리 서비스 (연)</span><b>${at?money(at):'-'}</b></div></div>
      <div class="tiny muted" style="margin-top:2px">생활 방식</div><div class="seg">${Object.entries(BUD).map(([k,b])=>`<button class="${(S.budget||'norm')===k?'on':''}" data-act="budg" data-v="${k}">${b.n}</button>`).join('')}</div>
      <div class="tiny muted">${BUD[S.budget||'norm'].d} · 집·차를 살수록 유지비가 늘어요</div>
      ${S.married?`<div class="small">💍 ${S.married.n} 씨와 결혼 (${S.married.y})</div>`:S.gf?`<div class="row small"><span class="sp">💑 ${jo(S.gf.n,'과','와')} 연애 중</span><span style="color:#e2557a">${'♥'.repeat(Math.max(1,Math.round(S.gf.aff/20)))}${'♡'.repeat(5-Math.max(1,Math.round(S.gf.aff/20)))}</span></div>`:''}</div>`}
  h+=`<div class="card" style="gap:0"><span class="lbl" style="padding-bottom:6px">🏏 장비 · 관리</span>${ITEMS.filter(it=>!it.hide&&it.cat!=='life'&&(it.t==='A'||it.t===ME.type)).map(it=>{const has=owned(it.id),phOk=(it.ph==null||it.ph===S.phase)&&!(it.id==='camp'&&S.campY===S.y),can=S.money>=it.p&&(!has||it.once)&&phOk;
    const until=S.me.items[it.id]&&S.me.items[it.id]!==true?S.me.items[it.id]-S.turn:0;
    return`<div class="row" style="padding:10px 0;border-bottom:1px solid var(--line)"><div class="sp"><div style="font-weight:700;font-size:.9rem">${it.n}</div><div class="tiny muted">${it.d}${until>0?` · ${until}턴 남음`:''}</div>${it.yr&&has?`<button class="chip ${(S.auto||{})[it.id]?'on':''}" style="margin-top:6px;cursor:pointer" data-act="autot" data-k="${it.id}">${(S.auto||{})[it.id]?'자동 갱신 ✓':'자동 갱신 꺼짐'}</button>`:''}</div>${has&&!it.once?'<span class="chip up">보유</span>':`<button class="btn sm ${can?'pri':''}" data-act="buy" data-k="${it.id}" ${can?'':'disabled'}>${money(it.p)}</button>`}</div>`}).join('')}</div>`;
  return h}

/* ===================== RETIRED ===================== */
function stints(){const out=[];const ord=S.rows.slice().sort((a,b)=>a.y-b.y);
  for(const r of ord){if(!(r.b.PA||r.p.outs||r.b.G||r.p.G||PRO.includes(r.lv)||r.lv==='hs'||r.lv==='univ'))continue;let name=r.team.replace(/ 퓨처스$/,''),kind=r.lv;
    if(r.lv==='fut'&&!/ 퓨처스$/.test(r.team))kind='mil';else if(r.lv==='fut'){const m=name.match(/\((MLB|NPB)\)/);kind=m?m[1]:'KBO'}
    const last=out[out.length-1];if(last&&last.name===name){last.y2=Math.max(last.y2,r.y);last.rows.push(r);if(PRO.includes(r.lv))last.kind=r.lv;continue}
    out.push({name,kind,y1:r.y,y2:r.y,rows:[r]})}
  return out.map(s=>{const t=TEAMS.find(t=>`${t.city} ${t.nick}`===s.name);return{...s,c:t?t.c:s.kind==='MLB'?'#0b3a6f':s.kind==='NPB'?'#b5121b':s.kind==='mil'?'#4b5d3a':'#8b95a1',tag:{hs:'고교',univ:'대학',mil:'군 복무',KBO:'KBO',NPB:'NPB',MLB:'MLB',fut:'KBO'}[s.kind]||''}})}
function vRetCard(){const e=S.ended,pit=isP(),t=careerTot(PRO),b=t.b,p=t.p,st=stints(),pro0=st.filter(s=>['KBO','NPB','MLB'].includes(s.kind)),ama=st.filter(s=>!pro0.includes(s)),pro=[];pro0.forEach(s=>{const l=pro[pro.length-1],rg=s.y1===s.y2?`${s.y1}`:`${s.y1}–${String(s.y2).slice(2)}`;if(l&&l.name===s.name){l.rg.push(rg);l.y2=s.y2}else pro.push({...s,rg:[rg]})});
  const debut=S.pro?S.pro.debut:null,main=pro.slice().sort((a,b)=>(b.y2-b.y1)-(a.y2-a.y1))[0],mc=main?main.c:'#191f28';
  const team=n=>/우승|메달|대회 최우수/.test(n)&&!/MVP/.test(n);const groups={},pers={};S.awards.filter(a=>!/금사자|청룡|봉황|고교|대학|U-18|청소년/.test(a.n)&&!(S.pro&&S.pro.debut&&a.y<S.pro.debut&&/대회|배/.test(a.n))).forEach(a=>{const k=a.n.replace(/^\d{4} /,'').replace(/\(.*\)/,'').trim();const g=team(k)?groups:pers;(g[k]=g[k]||[]).push(a.y)});
  const kindOf=n=>/MVP/.test(n)?'mvp':/골든/.test(n)?'glove':/우승/.test(n)?'ring':/메달/.test(n)?'medal':/왕|최다/.test(n)?'crown':'trophy';
  const tiles=pit?[['경기',p.G],['승',p.W],['ERA',era(p)],['탈삼진',p.K],['세이브',p.SV],['홀드',p.HLD||0],['WAR',t.w.toFixed(1)]]:[['경기',b.G],['타율',avg(b)],['홈런',b.HR],['타점',b.RBI],['안타',b.H],['WAR',t.w.toFixed(1)]];
  const yrs=S.rows.filter(r=>PRO.includes(r.lv)).map(r=>r.y),best=[...new Set(yrs)].map(y=>{const rs=S.rows.filter(r=>r.y===y&&PRO.includes(r.lv));let w=0;rs.forEach(r=>w+=rowWAR(r));return{y,w,rs}}).sort((a,b)=>b.w-a.w)[0];
  const grp=(o,em)=>Object.keys(o).length?`<div class="rc-tro">${Object.entries(o).sort((a,b)=>b[1].length-a[1].length).map(([n,ys])=>`<div class="rc-ti"><div class="rc-ic">${trophySVG(kindOf(n))}${ys.length>1?`<span class="cnt">×${ys.length}</span>`:''}</div><div class="rc-tn">${esc(n)}</div><div class="rc-ty">${ys.join(' · ')}</div></div>`).join('')}</div>`:`<div class="rc-none">${em}</div>`;
  return`<div class="rcard" style="--tc:${mc}">
    <div class="rc-top"><div class="rc-num${ME.num?'':' sm'}">${ME.num||retPosN().slice(0,2)}</div><div class="sp"><div class="rc-ey">${e.hof?'HALL OF FAME':'CAREER'} · ${debut||'-'}–${e.y}</div><div class="rc-nm">${esc(ME.name)}</div><div class="rc-meta">${retPosN()} · ${ME.hand} · ${e.age}세 은퇴</div></div>${e.hof?`<div class="rc-hof">${trophySVG('hof')}</div>`:''}</div>
    <div class="rc-tiles">${tiles.map(([k,v])=>`<div><b>${v}</b><span>${k}</span></div>`).join('')}</div>
    <div class="rc-sec">소속팀</div>
    <div class="rc-tl">${pro.map(s=>`<div class="rc-st"><i style="background:${s.c}"></i><span class="rc-yr">${s.rg.join('<br>')}</span><b>${esc(s.name)}</b><em>${s.tag}</em></div>`).join('')||'<div class="rc-none">프로 경력 없음</div>'}
      ${ama.length?`<div class="rc-ama">${ama.map(s=>`${s.tag} ${esc(s.name)} ${s.y1===s.y2?s.y1:`${s.y1}–${String(s.y2).slice(2)}`}`).join(' · ')}</div>`:''}</div>
    <div class="rc-sec">팀 트로피</div>${grp(groups,'우승 트로피는 끝내 들지 못했다')}
    ${(()=>{const mv={},ti={},ot={};for(const k in pers)(/MVP|최우수/.test(k)?mv:/왕|최다/.test(k)?ti:ot)[k]=pers[k];return`${Object.keys(mv).length?`<div class="rc-sec">MVP</div>${grp(mv,'')}`:''}${Object.keys(ti).length?`<div class="rc-sec">타이틀</div>${grp(ti,'')}`:''}<div class="rc-sec">개인 수상</div>${grp(ot,'그 밖의 수상 기록 없음')}`})()}
    <div class="rc-foot">${S.retNo?`<span style="background:#c9a227;color:#1a1300;font-weight:800">영구결번 No.${S.retNo.num}</span>`:''}<span>국가대표 ${S.hist.nat}회</span><span>올스타 ${S.hist.allstar}회</span><span>대기록 ${S.feats.filter(f=>f.big).length}개</span>${best&&best.w>0?`<span>커리어하이 ${best.y} (WAR ${best.w.toFixed(1)})</span>`:''}${S.pro&&S.pro.draft?`<span>${S.pro.draft.y+1} 드래프트 ${S.pro.draft.rd}R ${S.pro.draft.pick}순위</span>`:S.pro&&S.pro.dev?'<span>육성선수 출신</span>':''}</div>
  </div>`}
function vRetired(){const e=S.ended;let h=header();h+=`<button class="btn pri" style="width:100%" data-act="rcpo">🎞️ 커리어 리캡 다시 보기</button>`;h+=vRetCard();
  h+=`<div class="card" style="text-align:center;gap:6px"><span class="lbl">${e.y}년 · ${e.age}세</span><h1>${e.hof?'명예의 전당 헌액':'커리어 종료'}</h1><p class="muted">${esc(e.why)}. 커리어 점수 ${e.score}${e.hof?' — 전설로 남는다.':' (헌액 기준 110)'}</p></div>`;
  h+=`<div class="card"><span class="lbl">프로 통산</span><div style="font-weight:700">${lineFor(S.rows.filter(r=>PRO.includes(r.lv)))}</div>
    <div class="small muted">업적 ${Object.keys(S.ach).length}개</div></div>`;
  const best=featsClean(S.feats).filter(f=>f.big).slice(0,6);if(best.length)h+=`<div class="card"><span class="lbl">커리어 하이라이트</span>${best.map(f=>`<div class="small">★ ${f.y} ${esc(f.t)}</div>`).join('')}</div>`;

  h+=`<div class="btns"><button class="btn" data-act="tab" data-v="rec">기록 보기</button><button class="btn pri" data-act="reset2">새 커리어 시작</button></div>`;
  return h}

/* ===================== FOLLOW ===================== */
const FPOS={P:[150,150],C:[150,214],'1B':[203,136],'2B':[176,100],SS:[124,100],'3B':[97,136],LF:[66,66],CF:[150,34],RF:[234,66]};
const LAND={'1B':()=>[pick([90,150,210])+rn(0,12),78+rn(0,10)],'2B':()=>[pick([95,205])+rn(0,10),46+rn(0,8)],'3B':()=>[pick([60,240]),58],HR:()=>[pick([55,150,245])+rn(0,10),-6],GO:()=>[pick([124,176,97,203])+rn(0,6),112+rn(0,8)],FO:()=>[pick([66,150,234])+rn(0,10),40+rn(0,14)],LO:()=>[pick([124,176])+rn(0,6),98],K:null,BB:null};
function field(g,e){const my=g.my,bat=e.half,fld=1-e.half,cB=g.c[bat],cF=g.c[fld],me=e.last&&e.last.me;
  const tag=i=>i===my?'우리 팀':'상대';let ball='';
  if(e.last&&e.last.me&&LAND[e.last.t]){const[x,y]=LAND[e.last.t]();ball=`${['1B','2B','3B','HR'].includes(e.last.t)?'<circle class="impact" cx="150" cy="214" r="10" fill="none" stroke="#ffe27a" stroke-width="4"/>':''}<path class="traj" d="M150 214 Q${(150+x)/2} ${Math.min(y,150)-40} ${x} ${y}" stroke="#fff" stroke-width="2.5" fill="none" stroke-dasharray="5 4"/><circle class="ballp" cx="${x}" cy="${y}" r="4.5" fill="#fff" stroke="#e23b3b"/>`}
  const myP=fld===my?(isP()?'P':ME.pos):null;const fielders=Object.entries(FPOS).map(([p,[x,y]])=>`<g>${p===myP?`<circle cx="${x}" cy="${y}" r="13" fill="none" stroke="#ffe27a" stroke-width="2.5" class="mering"/><text x="${x}" y="${y-15}" text-anchor="middle" font-size="8" font-weight="900" fill="#ffe27a">나</text>`:''}<circle cx="${x}" cy="${y}" r="8.5" fill="${cF}" stroke="#fff" stroke-width="2"/><text x="${x}" y="${y+3}" text-anchor="middle" font-size="7.5" font-weight="800" fill="#fff">${p}</text></g>`).join('');
  const bases=[[203,154],[150,101],[97,154]];
  const runners=bases.map(([x,y],i)=>e.b&&e.b[i]?`<circle cx="${x}" cy="${y-12}" r="7.5" fill="${cB}" stroke="#ffe27a" stroke-width="2.5"/>`:'').join('');
  return`<div class="fieldw"><svg viewBox="0 0 300 240" class="fieldsvg" role="img" aria-label="경기장 상황">
    <path d="M150 230 L-10 70 Q150 -60 310 70Z" fill="#2f8a4e"/><path d="M150 230 L0 80 Q150 -30 300 80Z" fill="#3a9a5a"/>
    <path d="M150 226 L215 158 L150 92 L85 158Z" fill="#c9915a"/><path d="M150 208 L196 158 L150 112 L104 158Z" fill="#3a9a5a"/>
    <circle cx="150" cy="156" r="10" fill="#c9915a"/><path d="M150 226 L18 94 M150 226 L282 94" stroke="#fff" stroke-width="1.5" opacity=".8"/>
    ${bases.map(([x,y])=>`<rect x="${x-5}" y="${y-5}" width="10" height="10" transform="rotate(45 ${x} ${y})" fill="#fff"/>`).join('')}<path d="M144 220 h12 l-6 7z" fill="#fff"/>
    ${fielders}${runners}
    <circle cx="${bat===my&&me?150:150}" cy="222" r="8" fill="${cB}" stroke="${bat===my&&me?'#ffe27a':'#fff'}" stroke-width="2.5"/>
    ${ball}
    <g font-size="10" font-weight="800"><rect x="6" y="6" rx="6" width="96" height="40" fill="rgba(0,0,0,.45)"/><text x="14" y="22" fill="#fff">${e.inn}회${e.half?'말':'초'} · ${e.outs}아웃</text>
    <circle cx="16" cy="34" r="4" fill="${cB}"/><text x="24" y="38" fill="#fff">공격 ${g.ab[bat]}${bat===my?' · MY':''}</text></g>

  </svg></div>`}
function vFollow(g){const e=g.ev[Math.min(g.idx,g.ev.length-1)],n=Math.max(9,e.line[0].length,e.line[1].length);
  const row=i=>`<tr class="${i===g.my?'myrow':''}"><td class="tm">${crest(g.ab[i],18,g.c[i])}${g.ab[i]}${i===g.my?' <span class="mytag">MY</span>':''}</td>${[...Array(n)].map((_,k)=>`<td>${e.line[i][k]??''}</td>`).join('')}<td class="rr">${e.R[i]}</td><td>${e.Hh[i]}</td></tr>`;
  const shown=g.ev.slice(0,g.idx+1).reverse();
  return`<div class="row"><span class="lbl sp">${esc(g.sub)}</span><span class="tiny muted">${g.idx+1}/${g.ev.length}</span></div><h2>${esc(g.title)}</h2>
  <div class="board"><div class="lscore"><table><thead><tr><th></th>${[...Array(n)].map((_,i)=>`<th>${i+1}</th>`).join('')}<th class="rr">R</th><th>H</th></tr></thead><tbody>${row(0)}${row(1)}</tbody></table></div></div>
  ${g.idx>=g.ev.length-1?gameDone(g):e.b?field(g,e):''}${(()=>{const L=e.last;if(!L||!L.me)return'';const pit=isP(),t=L.t,big=pit?{K:['삼진!','K','#16305e']}[t]:{HR:['홈런!!','HR','#e23b3b'],'3B':['3루타!','3B','#f59f00'],'2B':['2루타!','2B','#f59f00']}[t];return big?`<div class="fxbig" style="--fx:${big[2]}" key="${g.idx}"><b>${big[0]}</b><span>${big[1]}</span></div>${ui.fxShown!==g.idx&&(t==='HR'||t==='K')?`<div class="fxfull ${t==='HR'?'hr':'k'}" key="f${g.idx}"><div class="fxburst"></div><div class="fxtxt">${t==='HR'?'HOME RUN!':'STRIKEOUT'}</div><div class="fxsub">${t==='HR'?(L.runs>=4?'만루 홈런!!':L.runs>=2?`${L.runs}점 홈런!`:'솔로 홈런!'):`${e.mk||''}번째 삼진`}</div>${t==='HR'?'<i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i>':''}</div>`:''}`:''})()}
  ${isP()&&e.pc!=null&&(e.mo||e.pc)?`<div class="pstat"><span>투구수 <b>${e.pc}</b></span><span>탈삼진 <b>${e.mk}</b></span><span>이닝 <b>${ip(e.mo||0)}</b></span></div>`:''}
  <div class="card"><div class="plog">${(g.idx>=g.ev.length-1?shown.slice(1,7):shown).map((x,i)=>`<div class="${x.c}${i===0?' now':''}">${esc(x.t).replace(/\n/g,'<br>')}</div>`).join('')}</div></div>
${false&&g.aid?(()=>{const ar=S.arts.find(x=>x.id===g.aid);return ar?`<div class="card"><div class="row"><span class="lbl sp">경기 후 반응</span><span class="tiny press">${ar.press}</span></div><b>${esc(ar.head)}</b>${ar.cm.slice(0,4).map(cmHtml).join('')}</div>`:''})():''}`}
/* ===================== SHEET & BAR ===================== */
const TIPS={
 fat:['피로','훈련과 경기 출전으로 쌓이는 몸의 부담이에요.',['높으면: 60↑부터 경기 능력치가 깎이고 부상 확률이 올라가요. 75↑면 수개월짜리 큰 부상 위험.','관리법: 훈련 계획에서 휴식 메뉴를 골라주세요. 수면 케어·영양사·트레이너(상점)도 회복을 도와요.','낮을수록 좋아요. 20~40 정도면 안정적이에요.']],
 form:['컨디션','타격감·구위의 흐름이에요. 매달 바뀌고, 좋거나 나쁜 흐름이 몇 달 이어지기도 해요.',['효과: 경기 중 모든 능력치에 ±5까지 보정. 프로에선 출전 결정에도 조금 반영돼요.','관리법: 직접 조절은 어려워요. 상점의 생활(집·차·반려견·요리사)에 투자하면 좋은 컨디션이 올 확률이 높아져요. 멘탈이 높을수록 좋은 쪽으로 기울고, 심리 상담(상점)과 "승부사" 특수능력이 슬럼프를 줄여줘요.']],
 chem:['팀 분위기','동료 선수들과의 관계예요.',['효과: 라커룸 분위기가 좋으면 팀 성적과 내 컨디션에 도움이 돼요.','떨어지는 일: 잦은 실책, 동료를 저버리는 선택. 올리는 일: 팀을 위한 선택, 이벤트에서 동료 챙기기.']],
 coach:['감독 신뢰','감독이 나를 얼마나 믿는지예요.',['효과: 주전·1군 기용, 연봉 협상, 포스팅 허락에 영향을 줘요.','올리는 법: 좋은 성적, 인터뷰에서 감독 칭찬, 성실한 선택. 기용 불만을 공개적으로 말하면 크게 떨어져요.']],
 fame:['인기','팬과 언론의 관심도예요.',['효과: FA 계약 금액, 올스타 선정, 광고 제의, 기사 댓글 반응 규모에 영향을 줘요.','올리는 법: 활약, 대기록, 수상, 팬 서비스·자선 같은 이벤트 선택.']],
 money:['자금','고교·대학 땐 용돈, 프로가 되면 연봉이 매달 들어와요.',['쓰는 곳: 상점에서 장비(능력치 즉시 +)와 1년짜리 관리 서비스(훈련 효율, 부상 예방)를 살 수 있어요.']],
 xp:['성장 포인트','특별한 순간에만 얻는 귀한 포인트예요. 살 수 없어요.',['얻는 법: 감독 칭찬(반기 활약), 쉬지 않고 성실하게 훈련한 반기, 대기록·수상·우승 같은 잊지 못할 순간, 기억에 남는 이벤트 선택.','쓰는 법: 능력치 탭 아래에서 특성을 배워요. 특정 상황의 안타·삼진·피안타 확률이 좋아져요.']],
 we:['워크에식','훈련 성실도예요.',['효과: 훈련으로 오르는 능력치 증가량↑ (훈련 효율 배수에 직접 반영)','올리는 법: 야간 자율훈련·새벽 특타·베테랑 조언 같은 이벤트 선택, 해외 개인 캠프(상점).']],
 men:['멘탈','압박을 이겨내는 힘이에요.',['효과: 포스트시즌·국제대회 같은 큰 경기와 득점권 같은 중요한 순간에 활약↑. 컨디션도 좋은 쪽으로 기울어요.','새 환경 적응: 1군 첫 시즌, 트레이드·이적한 새 팀, 메이저 진출이나 KBO 복귀처럼 낯선 환경에선 처음 몇 달 경기력이 조금 떨어져요. 멘탈이 높을수록 덜 흔들리고 더 빨리 적응해요.','올리는 법: 기본기 회복, 심리 상담(상점), 인터뷰에서 담담한 답변, 나이를 먹으며 조금씩.']],
 dur:['내구성','몸이 얼마나 튼튼한지예요.',['효과: 부상 빈도↓, 큰 부상 확률↓, 피로가 덜 쌓이고 더 빨리 회복, 30대 이후 노화 속도↓ (멘탈·워크에식과 함께)','올리는 법: 영양사 식단 관리(상점), 몸 관리를 고르는 이벤트 선택. 높을수록 오르기 어려워요.']],
 fcast:['예상 피로','지금 훈련 계획대로 진행하면 이번 기간 피로가 어느 정도 쌓일지 예측한 값이에요.',['"높음"부터는 부상 위험이 커져요. 휴식 메뉴로 조절하세요.','시즌 중엔 경기 피로가 더해져서 캠프보다 높게 나와요.']],
 limit:['최대치 100','모든 능력치는 20~100 스케일이고 최대치는 100이에요.',['100에 가까울수록 훈련 성장치가 줄어요. 타고난 재능에 따라 크는 속도가 달라요 — 직접 키워보며 알아가세요.','30세부터는 최대치가 서서히 낮아져요(주력·파워·구속 같은 신체 능력이 더 빨리).','고교~프로 3년차까지는 성장 속도가 빨라요.']]};
const tipB=(k,inner)=>`<button class="tipb" data-act="tip" data-k="${k}" aria-label="${TIPS[k][0]} 설명">${inner}<span class="qi">?</span></button>`;
function vTip(){const t=TIPS[ui.tip];if(!t)return'';return`<div class="scrim tipscrim" data-act="tipclose"><div class="tipcard" role="dialog" aria-modal="true"><div class="row"><b class="sp">${t[0]}</b><span class="tiny muted">탭해서 닫기</span></div><p class="small">${t[1]}</p>${t[2].map(x=>`<div class="tipli">${x}</div>`).join('')}</div></div>`}
function vSheet(){
  if(ui.tip)return vTip();
  if(ui.guide)return vGuide();
  if(ui.art!=null&&S.arts[ui.art])return vArticle(S.arts[ui.art]);
  if(ui.res!=null)return`<div class="scrim"><div class="sheet" role="dialog" aria-modal="true"><span class="ey">결과</span><p>${esc(ui.res)||'선택을 마쳤다.'}</p><button class="btn pri" data-act="resok">확인</button></div></div>`;
  const q=nextQ();if(ui.sheet!=='q'||!q||q.type==='game')return'';
  if(q.lb)return`<div class="scrim"><div class="sheet lbsheet" role="dialog" aria-modal="true"><div class="lbburst">100 → 110</div><h2 class="lbtitle">LIMIT BREAK</h2><p style="white-space:pre-line;text-align:center">${esc(q.text)}</p><button class="btn pri" data-act="pick" data-i="0">${esc(q.ch[0].t)}</button></div></div>`;
  return`<div class="scrim"><div class="sheet" role="dialog" aria-modal="true"><div class="grab"></div><span class="ey">${turnName()}${S._mid?` · ${S.m}월 (시즌 진행 중)`:""}</span><h2>${esc(q.title)}</h2><p style="white-space:pre-line">${esc(q.text)}</p>
    ${offerTbl(q)}
    ${(typeof optAttach804==='function'&&optAttach804(q),'')}${ui.offd1!=null&&q.ch[ui.offd1]&&q.ch[ui.offd1].d?offDetail(q,ui.offd1):q.ch.map((c,i)=>c.d?`<div class="chrow"><button class="choice" data-act="pick" data-i="${i}"><b>${esc(c.t)}</b>${c.s?`<span>${esc(c.s)}</span>`:''}</button><button class="chdet" data-act="offd1" data-i="${i}">조건<br>보기</button></div>`:`<button class="choice" data-act="pick" data-i="${i}"><b>${esc(c.t)}</b>${c.s?`<span>${esc(c.s)}</span>`:''}</button>`).join('')}
    <button class="btn sm" data-act="closeq">나중에 결정</button></div></div>`}
const GUIDE=[
 ['flow','시작하기',[['한 해는 3번','스프링캠프 → 전반기 → 후반기. 아래 파란 진행 버튼을 누르면 그 기간이 진행돼요.'],['목표','고교에서 잘해서 프로 지명 → 1군 주전 → FA·메이저리그 → 명예의 전당까지.'],['선택','계약·병역·이벤트 같은 선택이 가끔 떠요. 감독 신뢰와 인기, 커리어 방향이 달라져요.']]],
 ['train','훈련',[['훈련 탭','아래 메뉴의 훈련 탭에서 키우고 싶은 능력치 훈련을 메인 1개, 서브 1개 골라요.'],['메인·서브','메인으로 고른 훈련이 가장 크게 오르고, 서브도 꽤 많이 올라요. 오래 안 한 능력치는 조금씩 떨어질 수 있어요.'],['투수','투수는 아래쪽 변화구 연마에서 다듬을 변화구를 따로 골라요. 직구는 구위·구속 훈련으로 같이 올라가요. 선발은 쓸만한 구종 3개 이상, 불펜은 2개 이상이 목표예요.'],['피곤하면','피로가 높으면 서브를 휴식으로 바꾸세요.']]],
 ['xp','성장 포인트·특성',[['얻는 법','활약, 수상·대기록, 성실한 훈련, 이벤트로 얻어요.'],['쓰는 법','능력치 탭 아래 특성을 배워요. "득점권에서 안타 +5%"처럼 특정 상황에서 유리해져요. 비쌀수록 효과가 넓어요.']]],
 ['body','몸 관리',[['피로','60을 넘으면 경고, 75를 넘으면 큰 부상 위험이 커요. 휴식과 상점 관리 서비스로 조절하세요.'],['워크에식','높을수록 훈련 효율이 커져요. 같은 훈련을 해도 능력치가 더 많이 올라요.'],['멘탈','높을수록 큰 경기 활약이 좋아요. 포스트시즌·국제대회, 득점권 같은 중요한 순간에 강해져요.'],['내구성','좋을수록 피로가 덜 쌓여요. 부상도 덜 당하고 회복도 빨라요.'],['올리는 법','워크에식·멘탈·내구성은 이벤트 선택과 상점으로 올릴 수 있어요.']]],
 ['career','커리어 팁',[['메이저리그','종합 실력만큼 툴(능력치)이 고르게 좋아야 제안이 와요. 약점이 있으면 마이너에서 시작해요. 댓글 힌트를 참고하세요.'],['연봉·FA','잘하면 연봉 협상과 FA에서 크게 대우받아요.'],['병역','아시안게임 금메달·올림픽 메달이면 면제. 아니면 만 28세까지 상무·현역 중 선택해요.'],['큰 경기','포스트시즌·국제대회는 문자중계로 직접 봐요. 결과까지 건너뛸 수도 있어요.']]]];
function vGuide(){const cur=GUIDE.find(g=>g[0]===ui.guide)||GUIDE[0];const i=GUIDE.indexOf(cur),SH={xp:'성장·특성'};
  /* v858z: 높이 고정 · 탭 한 줄 · 내용만 스크롤 · [이전][다음] 버튼은 항상 같은 자리(첫 장은 이전 흐리게) · 닫기는 오른쪽 위 */
  return`<div class="scrim" data-act="guideclose"><div class="sheet guide g858z" role="dialog" aria-modal="true" data-stop="1"><div class="grab"></div>
  <div class="ghd"><span class="ey">게임 가이드 · ${i+1}/${GUIDE.length}</span><button class="gx" data-act="guideclose">닫기</button></div>
  <div class="gtabs">${GUIDE.map(g=>`<button class="chip ${g[0]===cur[0]?'on':''}" data-act="guide" data-v="${g[0]}">${SH[g[0]]||g[1]}</button>`).join('')}</div>
  <h2>${cur[1]}</h2>
  <div class="gbody">${cur[2].map(([t,d],k)=>`<div class="gitem"><span class="gnum">${k+1}</span><div><b>${t}</b><p class="small">${d}</p></div></div>`).join('')}</div>
  <div class="gfoot">${i>0?`<button class="btn" data-act="guide" data-v="${GUIDE[i-1][0]}">이전</button>`:`<button class="btn" disabled>이전</button>`}${i<GUIDE.length-1?`<button class="btn pri" data-act="guide" data-v="${GUIDE[i+1][0]}">다음: ${GUIDE[i+1][1]}</button>`:`<button class="btn pri" data-act="guideclose">시작하기</button>`}</div></div></div>`}
function vBar(){
  if(ui.screen==='title')return S?`<button class="btn" data-act="newgame">${ui.confirm==='newgame'?'저장이 지워져요. 한 번 더':'새 커리어'}</button><button class="btn pri glow" data-act="cont">이어하기 ▶</button>`:`<button class="btn pri glow" data-act="newgame">새 커리어 시작 ▶</button>`;
  if(!S)return`<button class="btn pri glow" data-act="start">${SCHOOLS[ui.cr.school].n} 입학 — 커리어 시작</button>`;
  if(ui.simming)return'';
  {const q0=nextQ();if(q0&&q0.type==='award')return`<button class="btn pri glow" data-act="awdone">계속</button>`}
  const q=nextQ();
  if(q&&q.type==='contract')return q.step===1?`<button class="btn pri" data-act="cdone">계속</button>`:`<button class="btn pri" data-act="csign" ${q.c.signed?'':'disabled'}>${q.c.signed?'서명하고 계약 완료':'서명란에 서명해 주세요'}</button>`;
  if(q&&q.type==='game'){const g=q.g,done=g.idx>=g.ev.length-1,cur=g.ev[g.idx];return done?`<button class="btn pri" data-act="gdone">경기 종료 · 계속</button>`:cur.c==='meup'?`<button class="btn" data-act="gend">결과까지</button><button class="btn pri" data-act="gnext">⚾ 내 타석 결과 보기</button>`:`<button class="btn" data-act="gend">결과까지</button><button class="btn" data-act="gpause">${ui.gpause?'▶ 계속 보기':'⏸ 일시정지'}</button>`}
  if(S.stage==='ret')return'';
  if(q)return`<button class="btn pri" data-act="openq">결정해야 할 일 ${S.queue.length}건</button>`;
  syncW();const ok=allocSum()===100;
  return`<button class="btn pri ${ok?'glow':''}" data-act="adv" ${ok?'':'disabled'}>${ok?`${turnName()} 진행 ▶`:`훈련 배분 합계를 100%로 (지금 ${allocSum()}%)`}</button>`}


/* ===================== AUDIO (generated, no files) ===================== */
const AU={ctx:null,pref:{music:true,sfx:true},timer:null,step:0,
  loadPref(){try{const p=JSON.parse(localStorage.getItem('bb_audio')||'null');if(p)this.pref=p}catch(e){}},
  savePref(){try{localStorage.setItem('bb_audio',JSON.stringify(this.pref))}catch(e){}},
  init(){if(this.ctx)return true;const C=typeof window!=='undefined'&&(window.AudioContext||window.webkitAudioContext);if(!C)return false;
    try{this.ctx=new C()}catch(e){return false}const c=this.ctx;
    this.out=c.createGain();this.out.gain.value=.8;this.out.connect(c.destination);
    this.mus=c.createGain();this.mus.gain.value=0;this.mus.connect(this.out);
    this.fx=c.createGain();this.fx.gain.value=.9;this.fx.connect(this.out);
    this.dl=c.createDelay(1);this.dl.delayTime.value=.42;const fb=c.createGain();fb.gain.value=.38;const lp=c.createBiquadFilter();lp.type='lowpass';lp.frequency.value=1500;
    this.dl.connect(lp);lp.connect(fb);fb.connect(this.dl);const wet=c.createGain();wet.gain.value=.35;lp.connect(wet);wet.connect(this.out);return true},
  unlock(){if(!this.init())return;if(this.ctx.state==='suspended')this.ctx.resume();this.iosFix();if(this.pref.music&&!this.timer)this.startMusic()},
  iosFix(){if(this.el)return;try{const sr=8000,n=sr/2,buf=new ArrayBuffer(44+n*2),v=new DataView(buf),w=(o,s)=>{for(let i=0;i<s.length;i++)v.setUint8(o+i,s.charCodeAt(i))};
    w(0,'RIFF');v.setUint32(4,36+n*2,true);w(8,'WAVE');w(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,sr,true);v.setUint32(28,sr*2,true);v.setUint16(32,2,true);v.setUint16(34,16,true);w(36,'data');v.setUint32(40,n*2,true);
    const el=new Audio(URL.createObjectURL(new Blob([buf],{type:'audio/wav'})));el.loop=true;el.setAttribute('playsinline','');const p=el.play();if(p&&p.catch)p.catch(()=>{});this.el=el}catch(e){}},
  noise(t,dur,vol,freq){const c=this.ctx,len=Math.floor(c.sampleRate*dur),b=c.createBuffer(1,len,c.sampleRate),d=b.getChannelData(0);for(let i=0;i<len;i++)d[i]=(Math.random()*2-1)*(1-i/len);
    const s=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();s.buffer=b;f.type='bandpass';f.frequency.value=freq;f.Q.value=.8;g.gain.value=vol;s.connect(f);f.connect(g);g.connect(this.fx);s.start(t)},
  note(f,t,dur,type,vol,dest,send=true){const c=this.ctx,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(f,t);
    g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(vol,t+Math.min(.05,dur*.25));g.gain.exponentialRampToValueAtTime(.0001,t+dur);
    o.connect(g);g.connect(dest);if(send)g.connect(this.dl);o.start(t);o.stop(t+dur+.05)},
  sfx(kind){if(!this.pref.sfx||!this.init())return;if(this.ctx.state==='suspended')this.ctx.resume();const t=this.ctx.currentTime+.01,n=(f,d,dt=0,v=.12,ty='sine')=>this.note(f,t+dt,d,ty,v,this.fx);
    const sq=(f,d,dt=0,v=.07)=>this.note(f,t+dt,d,'square',v,this.fx,false);
    const P={tap:()=>sq(1568,.045,0,.045),
      hr:()=>{this.noise(t,.06,1,3500);sq(523,.1,.05,.09);sq(659,.1,.13,.09);sq(784,.1,.21,.09);sq(1047,.45,.29,.1);[523,659,784,1047].forEach(f=>n(f*2,1.1,.42,.05,'triangle'));this.noise(t+.35,1.8,.22,900);this.noise(t+.6,1.4,.18,1400)},
      k:()=>{this.noise(t,.05,.9,6000);n(110,.18,0,.35,'sine');sq(988,.07,.1,.08);sq(1319,.16,.17,.09)},
      xbh:()=>{this.noise(t,.05,.9,3200);sq(659,.08,.05,.08);sq(880,.08,.12,.08);sq(1175,.25,.19,.09)},
      choose:()=>{sq(784,.06,0,.06);sq(1175,.1,.06,.06)},
      adv:()=>{sq(523,.07,0,.06);sq(659,.07,.07,.06);sq(784,.07,.14,.06);sq(1047,.18,.21,.07)},
      up:()=>{n(988,.08,0,.08);n(1319,.12,.05,.08)},
      hit:()=>{n(220,.08,0,.18,'triangle');n(880,.2,.03,.1);n(1320,.3,.1,.08)},
      run:()=>{n(660,.12,0,.07);n(880,.18,.06,.07)},
      feat:()=>{[784,988,1175,1568].forEach((f,i)=>n(f,.35,i*.08,.09))},
      win:()=>{[523,659,784,1047].forEach((f,i)=>n(f,.3,i*.1,.11,'triangle'));[523,659,784].forEach(f=>n(f*2,.9,.45,.05))},
      lose:()=>{n(392,.3,0,.08,'triangle');n(330,.45,.18,.07,'triangle')},
      pen:()=>{this.noise(t,.25,.5,3200);this.noise(t+.12,.2,.4,2600)},
      sign:()=>{[0,.18,.3].forEach(d=>this.noise(t+d,.07,.9,5000));[392,523,659,784,1047].forEach((f,i)=>n(f,.45,.35+i*.09,.12,'triangle'));[523,659,784,1047].forEach(f=>n(f,1.8,.85,.06,'sawtooth'));this.noise(t+.9,1.6,.35,1200)},
      lb:()=>{[262,330,392,523,659,784,1047].forEach((f,i)=>n(f,.4,i*.07,.1,'triangle'));[523,659,784,1047].forEach(f=>n(f,1.6,.55,.06,'sawtooth'));n(2093,1.2,.6,.05)}};
    (P[kind]||P.tap)()},
  startMusic(){if(!this.init())return;const c=this.ctx;if(!this.mlp){this.mlp=c.createBiquadFilter();this.mlp.type='lowpass';this.mlp.frequency.value=3200;this.mlp.connect(this.mus);this.dr=c.createGain();this.dr.gain.value=.9;this.dr.connect(this.mus)}
    this.mus.gain.cancelScheduledValues(c.currentTime);this.mus.gain.linearRampToValueAtTime(.55,c.currentTime+1.2);
    const mt=m=>440*Math.pow(2,(m-69)/12),sx=60/132/4,_=0;
    const SEC=[{ch:[[60,64,67],[59,62,67],[57,60,64],[57,60,65]],bs:[36,43,45,41],mel:[[72,_,76,_,79,_,76,_,84,_,79,_,76,_,74,_],[74,_,79,_,83,_,79,_,86,_,83,_,79,_,77,_],[76,_,72,_,76,_,81,_,79,_,76,_,72,_,76,_],[77,_,81,_,84,_,81,_,79,_,77,_,76,_,74,_]]},
      {ch:[[57,60,65],[59,62,67],[55,59,64],[57,60,64]],bs:[41,43,40,45],mel:[[81,_,_,79,77,_,79,_,81,_,84,_,81,_,_,_],[79,_,_,77,74,_,77,_,79,_,83,_,86,_,_,_],[79,_,76,_,71,_,76,_,79,_,83,_,79,_,76,_],[76,_,_,_,74,_,_,_,72,_,74,_,76,_,79,_]]}];
    const kick=t=>{const o=c.createOscillator(),g=c.createGain();o.frequency.setValueAtTime(150,t);o.frequency.exponentialRampToValueAtTime(42,t+.12);g.gain.setValueAtTime(.55,t);g.gain.exponentialRampToValueAtTime(.001,t+.16);o.connect(g);g.connect(this.dr);o.start(t);o.stop(t+.2)};
    const nz=(t,d,v,f,hp)=>{const len=Math.floor(c.sampleRate*d),b=c.createBuffer(1,len,c.sampleRate),a=b.getChannelData(0);for(let i=0;i<len;i++)a[i]=(Math.random()*2-1)*(1-i/len);const s=c.createBufferSource(),fl=c.createBiquadFilter(),g=c.createGain();s.buffer=b;fl.type=hp?'highpass':'bandpass';fl.frequency.value=f;g.gain.value=v;s.connect(fl);fl.connect(g);g.connect(this.dr);s.start(t)};
    let next=c.currentTime+.1;this.step=this.step||0;
    const sched=()=>{while(next<c.currentTime+.6){const st=this.step%128,sec=SEC[Math.floor(st/64)],bar=Math.floor((st%64)/16),k=st%16,t=next;
        if(k===0||k===8||(k===10&&bar%2))kick(t);if(k===4||k===12)nz(t,.13,.32,1900);if(k%2===0)nz(t,.035,.07,7500,1);
        if(k%4===0||k%4===3&&k!==15){const r=sec.bs[bar]+(k%8===4?12:0);this.note(mt(r),t,sx*1.8,'triangle',.11,this.mus,false)}
        if([2,6,10,14].includes(k))sec.ch[bar].forEach(m=>this.note(mt(m),t,sx*1.2,'square',.018,this.mlp,false));
        const m=sec.mel[bar][k];if(m)this.note(mt(m),t,sx*1.9,'square',.032,this.mlp,false);
        if(k===0)sec.ch[bar].forEach(m=>this.note(mt(m),t,sx*15,'sine',.022,this.mlp,false));
        this.step++;next+=sx}};
    sched();this.timer=setInterval(sched,150)},
  stopMusic(){if(!this.ctx)return;clearInterval(this.timer);this.timer=null;this.mus.gain.cancelScheduledValues(this.ctx.currentTime);this.mus.gain.linearRampToValueAtTime(0,this.ctx.currentTime+.6)},
  toggle(k){this.pref[k]=!this.pref[k];this.savePref();if(k==='music'){if(this.pref.music)this.unlock(),this.timer||this.startMusic();else this.stopMusic()}}};

/* ===================== RENDER & CONTROL ===================== */
function render(){
  const app=document.getElementById('app'),nav=document.getElementById('nav'),bar=document.getElementById('abar'),ov=document.getElementById('ov');
  _render(app,nav,bar,ov);postRender(app)}
function full(app,nav,bar,ov,html,cls){app.innerHTML=html;nav.hidden=true;bar.innerHTML=vBar();bar.className='abar nonav'+(cls||'');ov.innerHTML=''}
function _render(app,nav,bar,ov){
  if(ui.screen==='title')return full(app,nav,bar,ov,vTitle(),' dark');
  if(S&&ui.simming){ME=S.me;full(app,nav,bar,ov,vSim(),' empty');return}
  if(S&&S.stage==='ret'&&!S.recapSeen&&!nextQ()){S.recapSeen=1;ui.recap=0;save()}
  if(S&&ui.recap!=null){ME=S.me;full(app,nav,bar,ov,vRecap(),' dark');bar.innerHTML='';return}
  if(S&&nextQ()&&nextQ().type==='award'){ME=S.me;return full(app,nav,bar,ov,vAward(nextQ().a),' dark')}
  if(!S){if(!ui.cr)initCr();app.innerHTML=vCreate();nav.hidden=true;bar.innerHTML=vBar();bar.className='abar nonav';document.getElementById('ov').innerHTML='';return}
  ME=S.me;const q=nextQ();
  if(q&&q.type==='contract'){app.innerHTML=vContract(q);nav.hidden=true;bar.innerHTML=vBar();bar.className='abar nonav';document.getElementById('ov').innerHTML='';setupSig();return}
  if(q&&q.type==='game'){app.innerHTML=vFollow(q.g);nav.hidden=true;bar.innerHTML=vBar();bar.className='abar nonav';document.getElementById('ov').innerHTML='';return}
  app.innerHTML=(S.stage==='ret'&&ui.tab==='turn')?vRetired():({turn:vTurn,train:vTrainTab,stats:vStats,rec:vRecord,news:vNews,shop:vShop}[ui.tab]||vTurn)();
  nav.hidden=false;const b=vBar();bar.innerHTML=b;bar.className='abar'+(b?'':' empty');
  document.getElementById('navin').innerHTML=[['turn',S.stage==='ret'?'요약':'진행'],...(S.stage==='ret'?[]:[['train','훈련']]),['stats','능력치'],['rec','기록'],['news','기사'],['shop','상점']].map(([k,l])=>`<button class="tab ${ui.tab===k?'on':''}" data-act="tab" data-v="${k}">${icon(k)}${l}${k==='stats'&&ME.xp>=10&&S.stage!=='ret'?'<span class="dot"></span>':''}${k==='news'&&S.arts.length&&S.arts[0].seen!==true?'<span class="dot"></span>':''}</button>`).join('');
  document.getElementById('ov').innerHTML=vSheet()+(ui.toast?`<div class="toast" role="status">${esc(ui.toast)}</div>`:'')}
function postRender(app){document.body.classList.toggle('fs',ui.screen==='title'||!!(S&&(ui.simming||ui.recap!=null||(nextQ()&&nextQ().type==='award'))));
  ui.bump=null;ui.pop=false;
  if(ui.anim){app.classList.remove('enter');void app.offsetWidth;app.classList.add('enter');countUps();ui.anim=false;clearTimeout(ui.at);ui.at=setTimeout(()=>app.classList.remove('enter'),1400)}
  if(document.getElementById('confetti')&&!ui.confDone){ui.confDone=true;setTimeout(confetti,250)}
  gameAuto()}
function stepGame(g){g.idx=Math.min(g.ev.length-1,g.idx+1);const e=g.ev[g.idx];const ml=e.last&&e.last.me?e.last.t:null,hitT=['1B','2B','3B','HR'].includes(ml);AU.sfx(g.idx===g.ev.length-1?(g.win?'win':'lose'):e.c==='meup'?'tap':hitT&&!isP()?'hit':/sc/.test(e.c)?'run':'tap');if(e.c==='meup')haptic(15);else if(ml&&!isP())haptic(hitT?[18,20,30]:ml==='K'?[8,40,8]:10);else if(ml&&isP())haptic(ml==='K'?0:hitT?[30]:6);if(hitT)setTimeout(()=>{const f=document.querySelector('.fieldw');if(f){f.classList.remove('hitfx');void f.offsetWidth;f.classList.add('hitfx')}},60);if(e.last&&e.last.me&&!isP()&&['HR','2B','3B'].includes(e.last.t)){AU.sfx(e.last.t==='HR'?'hr':e.last.t==='K'?'k':'xbh');haptic(e.last.t==='HR'?[40,30,80,30,120]:[25,30,40]);setTimeout(()=>{if(e.last.t!=='K'){const a=document.getElementById('app');if(a){a.classList.remove('shake');void a.offsetWidth;a.classList.add('shake')}}ui.fxShown=g.idx},e.last.t==='K'?1150:2300);if(e.last.t==='HR'){ui.confDone=false;setTimeout(()=>{try{confetti()}catch(_){}},150)}}save()}
