/* ===================== 은퇴 카드: 사진 저장 · 공유 ===================== */
function loadH2C(){return new Promise((res,rej)=>{if(window.html2canvas)return res(window.html2canvas);const s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js';s.onload=()=>res(window.html2canvas);s.onerror=rej;document.head.appendChild(s)})}
function inlineStyles(src,dst){const cs=getComputedStyle(src);let t='';for(let i=0;i<cs.length;i++){const k=cs[i];t+=k+':'+cs.getPropertyValue(k)+';'}dst.setAttribute('style',t);for(let i=0;i<src.children.length;i++)if(dst.children[i])inlineStyles(src.children[i],dst.children[i])}
async function foCanvas(el,bg){const r=el.getBoundingClientRect(),w=Math.ceil(r.width),h=Math.ceil(el.scrollHeight),sc=2;const cl=el.cloneNode(true);inlineStyles(el,cl);cl.style.margin='0';
  const xml=new XMLSerializer().serializeToString(cl);const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}"><foreignObject width="100%" height="100%"><div xmlns="http://www.w3.org/1999/xhtml" style="background:${bg}">${xml}</div></foreignObject></svg>`;
  const img=new Image();img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);await img.decode();const c=document.createElement('canvas');c.width=w*sc;c.height=h*sc;const x=c.getContext('2d');x.scale(sc,sc);x.fillStyle=bg;x.fillRect(0,0,w,h);x.drawImage(img,0,0);return c}
async function rcCanvas(){const el=document.querySelector('#rt .rcard')||document.querySelector('.rcard');if(!el)throw new Error('no card');let h2c=null;try{h2c=await Promise.race([loadH2C(),new Promise((_,j)=>setTimeout(()=>j(0),5000))])}catch(e){}if(!h2c){const bg=getComputedStyle(document.body).backgroundColor||'#0b1220';return foCanvas(el,bg)}const bg=getComputedStyle(document.body).backgroundColor||'#0b1220';return h2c(el,{backgroundColor:bg,scale:Math.min(3,(window.devicePixelRatio||1)*1.5),useCORS:true,logging:false})}
function rcFileName(){try{return`${ME.name}_은퇴카드_${S.ended?S.ended.y:''}.png`}catch(e){return'retire_card.png'}}
function rcText(){try{const e=S.ended;return`⚾ 나의 야구 인생 — ${ME.name} (${retPosN()}) ${e&&e.hof?'명예의 전당 헌액!':'커리어 종료'} · ${e?e.age+'세 은퇴':''}`}catch(x){return'⚾ 나의 야구 인생 은퇴 카드'}}
async function rcSave(){try{toast('사진 만드는 중…');const c=await rcCanvas();c.toBlob(b=>{if(!b){toast('저장 실패');return}const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=rcFileName();document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(u);a.remove()},1500);toast('📸 은퇴 카드를 저장했어요')},'image/png')}catch(e){toast('저장할 수 없는 환경이에요')}}
async function rcShare(){try{toast('공유 준비 중…');const c=await rcCanvas();const b=await new Promise(r=>c.toBlob(r,'image/png'));const file=b?new File([b],rcFileName(),{type:'image/png'}):null,text=rcText(),url=location.href.split('#')[0];
  if(file&&navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({files:[file],title:'나의 야구 인생',text});return}
  if(navigator.share){await navigator.share({title:'나의 야구 인생',text,url});return}
  if(navigator.clipboard){await navigator.clipboard.writeText(text+' '+url);toast('공유 문구와 링크를 복사했어요')}else toast('이 브라우저는 공유를 지원하지 않아요')}catch(e){if(e&&e.name==='AbortError')return;toast('공유할 수 없는 환경이에요')}}
{const _vr=vRetired;vRetired=function(){let h=_vr();try{const btns=`<div class="row" style="gap:8px;margin:10px 0"><button class="btn pri" style="flex:1" data-act="rcsave">📸 사진 저장</button><button class="btn" style="flex:1" data-act="rcshare">📤 공유하기</button></div>`;const k=h.indexOf('<div class="rcard"');if(k>=0){let depth=0,i=k,end=-1;const re=/<\/?div\b[^>]*>/g;re.lastIndex=k;let m;while((m=re.exec(h))){if(m[0][1]==='/'){depth--;if(depth===0){end=m.index+m[0].length;break}}else depth++}if(end>0)h=h.slice(0,end)+btns+h.slice(end)}else h=btns+h}catch(e){}return h}}
if(typeof document!=='undefined')document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-act="rcsave"],[data-act="rcshare"]');if(!b)return;e.stopPropagation();e.preventDefault();b.getAttribute('data-act')==='rcsave'?rcSave():rcShare()},true);
