  txt(tx(q('.rc-ey')),70,130,34,'#ffd75a',800);txt(tx(q('.rc-nm')),70,230,96,'#fff',900);txt(tx(q('.rc-meta')),70,290,34,'rgba(255,255,255,.8)',600);
