  let Y=760;txt('소속팀',70,Y,30,'#ffd75a',800);Y+=50;qa('.rc-st').slice(0,4).forEach(s=>{txt(tx(s.querySelector('b'))+'  '+tx(s.querySelector('.rc-yr')).replace(/\s+/g,' '),90,Y,32,'#fff',700);Y+=46});
