function vHofSubmit(){if(!hofCfg()||!S||!S.ended)return'';const sent=S.hofSent&&S.hofSent===S.cid;
  if(sent)return`<div class="hof-box"><b>🏆 명예의 전당에 기록을 올렸어요!</b><span class="small muted">다른 플레이어들의 커리어와 순위를 비교해 보세요.</span><button class="btn pri" data-hof="open" data-v="hall">순위 보기</button></div>`;
  return`<div class="hof-box"><b>🏆 온라인 명예의 전당에 기록 올리기</b><span class="small muted">${esc(ME.name)}의 통산 기록이 전체 플레이어 순위에 올라가요. 한 커리어당 한 번만 올릴 수 있어요.</span><span class="small">명예의 전당 점수 <b>${hofWar().w.toFixed(1)}</b> <span class="muted">(${(()=>{const h=hofWar(),a=[];if(h.kbo)a.push('KBO '+h.kbo.toFixed(1));if(h.mlb)a.push('MLB '+h.mlb.toFixed(1)+'×2');if(h.npb)a.push('NPB '+h.npb.toFixed(1)+'×1.3');if(h.minor)a.push('마이너 '+h.minor.toFixed(1));return a.join(' · ')||'기록 없음'})()})</span></span>
  <input id="hofowner" class="hof-in" maxlength="12" placeholder="내 닉네임 (선택, 12자 이내)" value="${esc(ui.hofOwner||'')}"><div class="row" style="gap:8px"><button class="btn" style="flex:1" data-hof="open" data-v="hall">순위 보기</button><button class="btn pri" style="flex:1.4" data-hof="submit"${ui.hofBusy?' disabled':''}>${ui.hofBusy?'올리는 중…':'기록 올리기'}</button></div>${ui.hofErr?`<span class="small" style="color:var(--bad)">${esc(ui.hofErr)}</span>`:''}</div>`}
{const _vr19=vRetired;vRetired=function(){let h=_vr19();try{const box=vHofSubmit();if(box){const k=h.indexOf('<div class="row" style="gap:8px;margin:10px 0"><button class="btn pri" style="flex:1" data-act="rcsave">');if(k>=0)h=h.slice(0,k)+box+h.slice(k);else h=box+h}}catch(e){}return h}}
