{const _cr=spCardReady;spCardReady=function(){if(!nsHas(ME))return _cr();const u=spCardURL();if(_spCard&&_spCard.src===u&&_spCard.complete)return Promise.resolve();return new Promise(r=>{_spCard=new Image();_spCard.onload=_spCard.onerror=()=>r();_spCard.src=u})}}
