const NSPRG={"npg0_0": "sp/30be8439da21b8.webp", "npg0_1": "sp/a07d68aa23ff7e.webp", "npg0_2": "sp/554bb1c13f00c0.webp", "npg0_3": "sp/76f80941b9f65e.webp", "npg0_4": "sp/c8db046c22e2e6.webp", "npg0_5": "sp/7efa06de620288.webp", "npg0_6": "sp/37677175fe1834.webp", "npg0_7": "sp/185f2fdf16c543.webp", "npg1_0": "sp/7cb6ed70bbe0bb.webp", "npg1_1": "sp/45291ebeee5715.webp", "npg1_2": "sp/83cc729f777b4c.webp", "npg1_3": "sp/c9577da4474dcc.webp", "npg1_4": "sp/b0b5f65cb91720.webp", "npg1_5": "sp/36eac66ae7fb18.webp", "npg1_6": "sp/3a2fa297c97d37.webp", "npg1_7": "sp/62fd9b0632664b.webp", "npg2_0": "sp/2cd98c7e4c87f3.webp", "npg2_1": "sp/cae808aa649a43.webp", "npg2_2": "sp/7f7eb54dbd909d.webp", "npg2_3": "sp/971a135797ec9e.webp", "npg2_4": "sp/b82ae0fe32ff05.webp", "npg2_5": "sp/aff7f539d7b7f0.webp", "npg2_6": "sp/86f714ac1b51f4.webp", "npg2_7": "sp/bcb0bacd7a8a5e.webp"};
