async function hofPost(rec){return hofReq('hof_records',{method:'POST',headers:{'Content-Type':'application/json',Prefer:'return=minimal'},body:JSON.stringify(rec)})}
async function hofSend(rec){const post=async()=>{try{return await hofPost(rec)}catch(e){await new Promise(z=>setTimeout(z,1200));return hofPost(rec)}};let r=await post();if(r.status>=400&&r.status!==409&&rec.extra){const x=rec.extra;delete rec.extra;r=await post();rec.extra=x}if(!r.ok&&r.status!==409){try{const j=await r.clone().json();r._why=String(j.message||j.code||'').slice(0,80)}catch(e){}}return r}
hofSubmit=async function(owner){const rec=hofRecord(owner);try{rec.extra=hofExtra()}catch(e){}save();const r=await hofSend(rec);
  if(r.status===409){S.hofSent=S.cid;save();return'dup'}if(!r.ok){const e=new Error('http '+r.status);e.why=r._why||'';throw e}S.hofSent=S.cid;save();return'ok'};
