{const _cm=comments;comments=function(tone,x){const out=_cm(tone,x);try{out.forEach(c=>{if(c&&c.t)c.t=josaFix(c.t);if(c&&Array.isArray(c.re))c.re.forEach(r=>{if(r&&typeof r==='object'&&r.t)r.t=josaFix(r.t)})})}catch(e){}return out}}

