    const tour=/은퇴 투어/.test(String(S.ended&&S.ended.why||'')),kids=(S.children||[]).filter(k=>k&&k.n&&!/째|막내/.test(k.n));
    const nmI=n=>{const c=n.charCodeAt(n.length-1)-0xAC00;return c>=0&&c<11172&&c%28?n+'이':n};
    const oneC=(S.retNo&&!/MLB/.test(String(S.retNo.team)))||(clubs.length===1&&seasons>=10);
    const FQ=[],qa=(...x)=>FQ.push(...x);
