      const AB={hr:'당신의 홈런이 우리의 여름이었습니다',sb:'당신의 발이 우리의 심장을 뛰게 했습니다',def:'당신이 지킨 건 아웃카운트가 아니라 우리의 마음이었습니다',hit:'당신의 안타가 우리의 하루를 바꿨습니다',k:'당신의 삼진에 우리는 함께 소리 질렀습니다',win:'당신이 던지는 날은 이기는 날이었습니다',sv:'9회는 언제나 당신의 시간이었습니다',hld:'당신이 놓은 다리 위로 우리는 승리를 건넜습니다'};
      const BN=['당신이 있어 행복했습니다','당신은 우리의 자부심이었습니다','당신의 야구는 끝나도 우리의 응원은 끝나지 않습니다','수고했어요, 우리의 영웅'];
      if(AB[arch])BN.push(AB[arch],AB[arch]);if(num)BN.push(`고마웠어요, 우리의 ${num}번`);if(num&&S.retNo)BN.push(`${num}번은 영원히 당신의 것`);if(role)BN.push(`영원한 우리의 ${role}`);
