  pend.forEach(([i,k])=>{const c=cell(i,k);if(c)c.textContent=''});for(let i=0;i<2;i++){const c=rc(i);if(c&&pend.some(p=>p[0]===i))c.textContent=run[i]}
  const xc=(i,j)=>rows[i]&&rows[i].children[2+Math.max(9,n)+j];if(P0.X)for(let i=0;i<2;i++)for(let j=0;j<3;j++){const c=xc(i,j);if(c)c.textContent=P0.X[i][j]}
