if(typeof document!=='undefined'){try{const st=document.createElement('style');st.textContent='.psf .psf-row:not(.on),.psf .psf-h:not(.on){display:none}.psf .psf-row.on,.psf .psf-h.on{animation:psfIn .35s ease both}@keyframes psfIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}';document.head.appendChild(st)}catch(e){}}
function psfRevealH(r){try{let p=r.previousElementSibling;while(p&&!p.classList.contains('psf-row')){if(p.classList.contains('psf-h'))p.classList.add('on');p=p.previousElementSibling}}catch(e){}}
psfAnimate=function(){try{const rows=[...document.querySelectorAll('.psf-row')];if(!rows.length)return;clearTimeout(ui.psfT);const q=nextQ();const key=q&&q.lines?JSON.stringify(q.lines).length+':'+q.lines.length:'';
  const fin=r=>{psfRevealH(r);r.classList.add('on','done');r.querySelector('.psf-a').textContent=r.dataset.a;r.querySelector('.psf-b').textContent=r.dataset.b};
  if(ui.psfSkip===key){rows.forEach(fin);psfBar(true);return}
  let k=0;const step=()=>{if(k>=rows.length){psfBar(true);return}const r=rows[k++];psfRevealH(r);r.classList.add('on');const A=+r.dataset.a,B=+r.dataset.b,n=Math.max(A,B,1);let t=0;
    const tick=()=>{t++;const fa=Math.min(A,Math.round(A*t/n)),fb=Math.min(B,Math.round(B*t/n));r.querySelector('.psf-a').textContent=fa;r.querySelector('.psf-b').textContent=fb;
      if(t<n)ui.psfT=setTimeout(tick,Math.max(45,320/n));else{r.classList.add('done');try{AU.sfx('tap')}catch(e){}ui.psfT=setTimeout(step,520)}};
    try{r.scrollIntoView({block:'nearest',behavior:'smooth'})}catch(e){}ui.psfT=setTimeout(tick,300)};
  ui.psfKey=key;step()}catch(e){}};
if(typeof document!=='undefined')document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-act="psfskip"]');if(!b)return;document.querySelectorAll('.psf .psf-h').forEach(h=>h.classList.add('on'))},true);

/* 출루형 타자 댓글: 세이버·현대야구 / 타율 대비 출루 / 볼넷 경기 / 연차·성적별 말투 / 리드오프 */
function obpLines(x){try{if(isP()||S.stage!=='pro'||!S.pro)return null;const lg=S.pro.league,{b}=yearTot(S.y,[lg]);if(!b||b.PA<150)return null;
  const ab=Math.max(1,b.AB),avg=b.H/ab,obp=(b.H+b.BB)/Math.max(1,ab+b.BB),bbp=b.BB/Math.max(1,b.PA),game=!!(x&&x.gPA!=null);
  const gBB=game?(x.gBB||0):0,gOB=game?((x.gH||0)+(x.gBB||0)):0;
  if(!(obp>=.39||bbp>=.12)&&!(game&&(gBB>=2||gOB>=3)&&obp>=.36))return null;
  const g=perfGrade(),rookie=(typeof proYears==='function'?proYears():2)<=1,mlbExp=lg==='MLB'||S.rows.some(r=>r.lv==='MLB'),O=obp.toFixed(3).replace(/^0/,''),A=avg.toFixed(3).replace(/^0/,'');
  const low=g==='bad'||(rookie&&g!=='good'&&g!=='elite'&&avg<.26);
  const L=[];
  if(game&&gBB>=2)L.push('오늘도 투수 투구수 다 빼먹고 걸어나가네 ㅋㅋ','유인구에 배트가 안 나온다 투수 입장에선 미치는 타자',`볼넷 ${gBB}개 골라낸 게 오늘 경기 숨은 공헌임`,'이런 타자가 앞에 있으면 중심타선 타점 밥상 차려짐');
  if(low){L.push('볼넷은 잘 고르는데 칠 생각은 있냐 ㅋㅋ','출루율 장인 소리 들으려면 일단 방망이도 좀 돌려라','걸어나가는 거 말고 보여준 게 없음 ㅋㅋ');return L}
  if(avg<=.27&&obp>=.38)L.push('타율만 보고 까는 사람들 출루율 좀 봐라',`타율 ${A}인데 출루율 ${O}면 그냥 좋은 타자임`,'옛날 야구 기준이면 저평가, 지금 기준이면 핵심 타자','안타는 적어도 아웃카운트를 안 준다');
  L.push(obp>=.4?'출루율 .4 넘는 타자는 세이버 쪽에서 제일 좋아하는 유형이지':'세이버메트릭스가 사랑하는 타자 그 자체','타율보다 출루율 봐라 이게 현대야구다','아웃 안 당하는 게 제일 큰 능력이라는 걸 보여주는 선수','요즘 구단들이 돈 쓰는 타입이 딱 이런 타자임','wOBA 찍어보면 체감보다 훨씬 높게 나올 듯','볼넷도 안타랑 똑같이 1루 간다 이걸 아는 타자');
  if(g==='avg')L.push('선구안은 이미 됐고 장타만 붙으면 무섭겠다','눈은 확실한 타자라 컨택만 좀 늘면 크게 될 듯');
  if((g==='good'||g==='elite')){if(!mlbExp)L.push('이 출루율이면 메이저 스카우트들이 좋아할 유형','세이버 좋아하는 메이저 구단들이 탐낼 타자');else L.push('메이저에서도 출루율 이 정도면 리그 정상급','현지 분석가들이 좋아할 만한 타석 접근법')}
  if(S.order===1)L.push('1번 타자는 원래 이런 애가 해야 됨','출루율 높은 리드오프 있으면 그 팀 득점력 확 달라짐');else L.push('타순 어디 놔도 앞에서 판 깔아주는 타입');
  return L}catch(e){return null}}
{const _cOB=comments;comments=function(tone,x){let out=_cOB(tone,x);try{if(!Array.isArray(out)||isP()||(x&&x.intl))return out;if(x&&(x.ps||x.big)||/^ps|champ|title|award|injury|inj|comeback|retire|hof|record|love|wed|baby|kid|mil|draft|scandal|^ring$|^ws$|^gold$|medal|legend|^mvp/i.test(String(tone)))return out;if(['abroad','contract','faBig','faFair','salary','mlbBig','milback','trade','love','retire','scandal','injury'].includes(tone))return out;
  if(out.some(c=>/눈야구|볼넷 골라|선구안|출루 머신|출루율/.test(c&&c.t||'')))return out;const key=S.y+':'+S.phase+(x&&x.gPA!=null?':g':':s');if(S._obpK===key||R()>=.25)return out;
  const L=(obpLines(x)||[]).map(josaFix).filter(t=>!seenHas(t));if(!L.length)return out;const t=pick(L);seenAdd(t);S._obpK=key;out.splice(Math.min(out.length,ri(1,3)),0,mkC(t,[],{}))}catch(e){}return out}}

/* 부상 기사: 성적 비판·놀림 댓글 제거 (걱정·응원만) */
{const _cInj=comments;comments=function(tone,x){let out=_cInj(tone,x);try{if(tone!=='injury'||!Array.isArray(out))return out;const BAD=/선풍기|삼진 \d+개|헛스윙|수비라도|ERA|타율|OPS|못하|까는|욕먹|먹튀|방출|공갈포|볼넷 쇼|탈삼진|홈런 \d+|ㅋㅋ/,OK=/부상|복귀|건강|회복|아프|다치|관리|혹사|재활|몸|쉬|기다|수술|걱정|빨리|천천히/;
  out=out.filter(c=>{const t=String(c&&c.t||'');return !BAD.test(t)||OK.test(t)})}catch(e){}return out}}

/* 연애 이벤트: 선택 전에 이미 헤어졌거나 결혼한 경우 오류 없이 넘어가기 */
{for(const k of ['gift','lv']){const _a=ACT[k];if(typeof _a==='function')ACT[k]=function(a){if(!S.gf&&!S.married)return'이미 지나간 인연이다. 마음을 정리하고 야구에 집중하기로 했다.';if(!S.gf&&S.married&&S.spouse)return _a.call(this,a);try{return _a.call(this,a)}catch(e){return'마음만 전하고 넘어갔다.'}}}}

/* 계약·이적 기사: 경기 장면/컨디션 댓글 제거 */
{const _cCT=comments;comments=function(tone,x){let out=_cCT(tone,x);try{const CTT=['move','franMove','kmove','abroad','contract','faBig','faFair','salary','mlbBig','milback','trade'];if(!Array.isArray(out)||!(CTT.includes(tone)||(tone==='mix'&&x&&typeof x==='object'&&!Object.keys(x).length)))return out;
  const G=/오늘 경기|구위|타석|등판|타구|출근 도장|강림|애 보느라|잠 못 잤|선풍기|원바운드|헛스윙|삼진|볼넷 쇼|오늘도 (잘|못)|응원단장|텐션|존재감 물올|오늘은 조용|오늘도 [가-힣]{1,4}했다/;out=out.filter(c=>{const t=String(c&&c.t||'');return !G.test(t)&&!(/오늘/.test(t)&&!/오늘 (야구 커뮤|댓글|기사|발표|오피셜)/.test(t))})}catch(e){}return out}}

/* 부상 중: 대표팀 예비 명단·특별 훈련·개인 캠프 제안이 큐에 남아 있으면 제거 (대표팀은 자동 고사 처리) */
function injPurgeQ(){try{if(!S||!ME||!ME.inj||!Array.isArray(S.queue))return;const RX=/대표팀 예비 명단|특별 훈련 제안|해외 개인 캠프|캠프 개인 훈련/;S.intlPick=S.intlPick||{};
  S.queue=S.queue.filter(q=>{if(!q||q.type||!RX.test(q.title||''))return true;const m=String(q.title).match(/(\d{4}\s*\S*(WBC|아시안게임|올림픽|프리미어12)[^ ]*)/);const a=(q.ch||[]).find(c=>c.arg&&c.arg.n);if(a)S.intlPick[a.arg.n]=0;else if(m)S.intlPick[m[1]]=0;return false})}catch(e){}}
{const _advI=advance;advance=function(){const r=_advI.apply(this,arguments);injPurgeQ();return r}}
{const _chI=choose;choose=function(i){const r=_chI.apply(this,arguments);injPurgeQ();return r}}

/* ===== 온라인 명예의 전당: 투수는 등록한 보직의 WAR만 점수에 반영 (통산 WAR·은퇴 카드는 그대로) =====
   선발 = 선발+불펜 시즌 전부 · 마무리 = 10세이브+ 구원 시즌 · 불펜(셋업) = 10홀드+ 또는 기타 구원 시즌 · 10세이브·10홀드 동시면 양쪽 인정 */
function hofSeasons(){const by={};(S.rows||[]).forEach(r=>{const k=HOF_W[r.lv];if(!k||!r.p)return;const key=r.y+'|'+r.lv;const o=by[key]=by[key]||{lv:r.lv,p:blankP(),w:0};addTo(o.p,r.p);let v=0;try{v=rowWAR(r)}catch(e){}if(isFinite(v))o.w+=v});
  return Object.values(by).filter(o=>o.p.G>0).map(o=>{const p=o.p,sp=(p.GS||0)>=p.G/2,cl=!sp&&(p.SV||0)>=10,su=!sp&&(p.HLD||0)>=10;return Object.assign(o,{SP:true,CL:cl,RP:!sp&&(su||!cl),isSP:sp})})}
function hofWarRole(role){const o={kbo:0,mlb:0,npb:0,minor:0,w:0};hofSeasons().forEach(s=>{if(!s[role])return;const k=HOF_W[s.lv],v=s.w;if(s.lv==='KBO')o.kbo+=v;else if(s.lv==='MLB')o.mlb+=v;else if(s.lv==='NPB')o.npb+=v;else o.minor+=v;o.w+=v*k});return o}
function hofRoleOpts(){const ss=hofSeasons(),o=[];if(ss.some(s=>s.isSP))o.push('SP');if(ss.some(s=>s.CL))o.push('CL');if(ss.some(s=>s.RP))o.push('RP');if(!o.length)o.push('RP');return o}
function hofRoleNow(){const o=hofRoleOpts();let r=S.hofRole;if(!o.includes(r)){let d='RP';try{d=hofProle(careerTot(PRO).p)}catch(e){}r=o.includes(d)?d:o[0]}return r}
{const _hrR=hofRecord;hofRecord=function(owner){const rec=_hrR(owner);try{if(rec.kind==='P'){const role=hofRoleNow(),h=hofWarRole(role),r1=v=>Math.round(v*10)/10;rec.prole=role;rec.wwar=r1(h.w);rec.kbo_war=r1(h.kbo);rec.mlb_war=r1(h.mlb);rec.npb_war=r1(h.npb);rec.minor_war=r1(h.minor)}}catch(e){}return rec}}
const HOF_RN={SP:'선발',CL:'마무리',RP:'불펜(셋업)'};
function hofInfoBox(){return`<div class="hof-note" style="text-align:left;line-height:1.6"><b>명예의 전당 점수 계산</b><br>
· 점수 = KBO WAR ×1.0 + MLB WAR ×2.0 + 마이너 WAR (AAA ×0.5 · AA 이하 ×0.3)<br>· 퓨처스(2군)·고교·대학 기록은 빠져요.<br><br>
<b>투수는 등록한 보직의 WAR만 점수에 들어가요</b><br>
· 선발: 선발로 뛴 시즌 + 불펜으로 뛴 시즌 WAR 전부<br>· 마무리: 구원으로 10세이브 이상 올린 시즌만<br>· 불펜(셋업): 구원으로 10홀드 이상 올린 시즌 + 기타 구원 시즌<br>
· 한 시즌에 10세이브·10홀드를 모두 넘기면 마무리·불펜 양쪽에 인정<br>· 등판의 절반 이상을 선발로 나선 시즌은 선발 시즌이에요.<br>
· 보직은 은퇴 후 기록을 올릴 때 직접 골라요 (뛰어본 보직만 선택 가능).<br><br>
<span class="muted">통산 WAR·은퇴 카드·기록 화면은 보직과 관계없이 모든 WAR를 그대로 보여줘요.</span></div>`}
{const _vhH=vHofHall;vHofHall=function(){let h=_vhH();try{h=h.replace(/<div class="hof-note">[\s\S]*?<\/div>/,`<div class="hof-note">은퇴한 모든 플레이어의 커리어 중 포지션별 명예의 전당 점수 1위가 올라요. <button class="chip" data-hofx="info" style="margin-left:4px;padding:2px 8px">ⓘ 계산 방식</button></div>${ui.hofInfo?hofInfoBox():''}`)}catch(e){}return h}}
{const _vhR=vHofRank;vHofRank=function(kind){let h=_vhR(kind);try{h=`<div class="row" style="justify-content:flex-end;margin:-2px 0 6px"><button class="chip" data-hofx="info" style="padding:2px 8px">ⓘ 점수 계산 방식</button></div>${ui.hofInfo?hofInfoBox():''}`+h}catch(e){}return h}}
{const _vhS=vHofSubmit;vHofSubmit=function(){let h=_vhS();try{if(!h||!S||!S.ended||!isP()||(S.hofSent&&S.hofSent===S.cid))return h;const ops=hofRoleOpts(),cur=hofRoleNow(),sc=hofWarRole(cur).w;
  {const hw=hofWarRole(cur),a=[];if(hw.kbo)a.push('KBO '+hw.kbo.toFixed(1));if(hw.mlb)a.push('MLB '+hw.mlb.toFixed(1)+'×2');if(hw.npb)a.push('NPB '+hw.npb.toFixed(1)+'×1.3');if(hw.minor)a.push('마이너 '+hw.minor.toFixed(1));h=h.replace(/명예의 전당 점수 <b>[^<]*<\/b>( <span class="muted">\([^<]*\)<\/span>)?/,`명예의 전당 점수 <b>${sc.toFixed(1)}</b> <span class="muted">(${HOF_RN[cur]} 기준 · ${a.join(' · ')||'기록 없음'})</span>`)}
  const sel=`<div class="small" style="margin:4px 0 2px">등록할 보직 <button class="chip" data-hofx="info" style="padding:1px 7px">ⓘ</button></div><div class="seg">${ops.map(k=>`<button class="${k===cur?'on':''}" data-hofx="role" data-v="${k}">${HOF_RN[k]} ${hofWarRole(k).w.toFixed(1)}</button>`).join('')}</div>${ui.hofInfo?hofInfoBox():''}`;
  const k=h.indexOf('<input id="hofowner"');if(k>=0)h=h.slice(0,k)+sel+h.slice(k)}catch(e){}return h}}
if(typeof document!=='undefined')document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-hofx]');if(!b)return;e.stopPropagation();e.preventDefault();const k=b.getAttribute('data-hofx');if(k==='info')ui.hofInfo=!ui.hofInfo;else if(k==='role'){S.hofRole=b.getAttribute('data-v');try{save()}catch(x){}}render()},true);

/* 명예의 전당 기본 보직 = 실제로 가장 많이 던진 보직 (이닝 기준) */
function hofMainRole(){try{const t={SP:0,CL:0,RP:0};hofSeasons().forEach(s=>{const o=s.p.outs||0;if(s.isSP)t.SP+=o;else if(s.CL)t.CL+=o;else t.RP+=o});return Object.keys(t).sort((a,b)=>t[b]-t[a])[0]}catch(e){return'SP'}}
hofRoleNow=function(){const o=hofRoleOpts();let r=S.hofRole;if(!o.includes(r)){const d=hofMainRole();r=o.includes(d)?d:o[0]}return r};

/* 명예의 전당(수정): 마무리·불펜 등록 = 구원 시즌 WAR 전부(선발 시즌 제외) · 선발 = 전부 */
hofSeasons=function(){const by={};(S.rows||[]).forEach(r=>{const k=HOF_W[r.lv];if(!k||!r.p)return;const key=r.y+'|'+r.lv;const o=by[key]=by[key]||{lv:r.lv,p:blankP(),w:0};addTo(o.p,r.p);let v=0;try{v=rowWAR(r)}catch(e){}if(isFinite(v))o.w+=v});
  return Object.values(by).filter(o=>o.p.G>0).map(o=>{const sp=(o.p.GS||0)>=o.p.G/2;return Object.assign(o,{SP:true,CL:!sp,RP:!sp,isSP:sp})})};
hofRoleOpts=function(){const ss=hofSeasons(),o=[];if(ss.some(s=>s.isSP))o.push('SP');const rel=ss.filter(s=>!s.isSP);if(rel.length){const sv=rel.reduce((a,s)=>a+(s.p.SV||0),0),hd=rel.reduce((a,s)=>a+(s.p.HLD||0),0);if(sv>0||!hd)o.push('CL');if(hd>0||!sv)o.push('RP')}if(!o.length)o.push('RP');return o};
hofMainRole=function(){try{const ss=hofSeasons();let sp=0,rl=0,ns=0,nr=0,sv=0,hd=0;ss.forEach(s=>{if(s.isSP){sp+=s.p.outs||0;ns++}else{rl+=s.p.outs||0;nr++;sv+=s.p.SV||0;hd+=s.p.HLD||0}});const isSp=ns!==nr?ns>nr:sp>=rl;if(!ss.length)return ME.pos==='RP'?'RP':'SP';return isSp?'SP':(sv>=hd?'CL':'RP')}catch(e){return'SP'}};
HOF_RN.RP='불펜';
hofInfoBox=function(){return`<div class="hof-note" style="text-align:left;line-height:1.6"><b>명예의 전당 점수 계산</b><br>
· 점수 = KBO WAR ×1.0 + MLB WAR ×2.0 + 마이너 WAR (AAA ×0.5 · AA 이하 ×0.3)<br>· 퓨처스(2군)·고교·대학 기록은 빠져요.<br><br>
<b>불펜 투수(마무리·불펜)는 선발로 뛴 시즌의 WAR이 명예의 전당 점수와 순위에 반영되지 않아요.</b><br>
· 선발 투수는 불펜으로 뛴 시즌까지 모두 반영돼요.<br>· 은퇴 후 기록을 올릴 때 실제로 가장 많이 뛴 보직이 기본으로 선택돼요.<br><br>
<span class="muted">통산 WAR·은퇴 카드·기록 화면에는 모든 WAR가 그대로 반영돼요.</span></div>`};

/* ===== 드래프트: 포지션 핵심 툴 반영 + 스카우트 평가 댓글 ===== */
