function ctMaxY(lg){const a=age();if(lg==='MLB')return a<=26?12:a<=28?10:a<=30?8:a<=32?6:a<=34?4:a<=36?3:a<=39?2:1;return a<=27?8:a<=29?6:a<=31?5:a<=33?4:a<=35?3:a<=37?2:1}
