{const _agX=agingTick;agingTick=function(){const a=age(),b={...ME.r};_agX();try{if(a<38)return;const m=Math.min(.35,.15+.05*(a-38));for(const k in b){if(typeof b[k]==='number'&&typeof ME.r[k]==='number'&&ME.r[k]<b[k])ME.r[k]=cl(ME.r[k]-(b[k]-ME.r[k])*m,20,99)}}catch(e){}}}

