  const rp=['CL','SU','MR'].includes(S.prevRole)||x.role==='rp'||x.role==='CL';const played=P?ipO>0:pa>0;if(!played)return out;
  const good=P?(rp?(ipO>=3&&!ra):(ipO>=15&&ra<=2)):(hr>=1||h>=2||rbi>=2),bad=P?(ra>=3||(rp&&ra>=1&&!win)):(pa>=3&&h===0);
  const WS=/월드시리즈/.test(t),KS=/한국시리즈/.test(t),gm=+(t.match(/(\d)차전/)||[0,0])[1],mg=Math.abs((x.myR||0)-(x.opR||0)),WC=/와일드카드/.test(t);
  /* 흐름 기록 (이번 가을) */
  const key=S.y+'|'+t;S.psTr=S.psTr&&S.psTr.y===S.y?S.psTr:{y:S.y,seq:[],k:{}};let prev=S.psTr.seq.slice();if(!S.psTr.k[key]){S.psTr.k[key]=1;S.psTr.seq.push(good?1:bad?-1:0)}else prev=prev.slice(0,-1);
  const endS=(x.clinch&&win)||(!!x.elim&&!win),add=[],put=(s,re,up)=>{s=josaFix(s);if(endS&&/다음|내일|7차전 한 판/.test(s))return false;if(seenHas(s)||out.some(c=>c&&c.t===s)||add.some(c=>c.t===s))return false;seenAdd(s);add.push(mkC(s,re&&re.length?[{nk:pick(NICKS),t:josaFix(pick(re)),up:ri(60,900)}]:[],{up:up||ri(1500,6500),must:1}));return true};
  const P1=a=>a[Math.floor(R()*a.length)];
