/* 계약·이적 기사: 경기 얘기 댓글/대댓글 최종 제거 (대댓글 포함) */
{const CT2=['move','franMove','kmove','abroad','contract','faBig','faFair','salary','mlbBig','milback','trade'];
 const G2=/오늘 경기|경기보다|구위|타석|등판|타구|헛스윙|삼진|감독 표정|중계 카메라|폼 미쳤|몸만 출근|리모컨|구종 하나|출루율이면|세이버 좋아하는|볼배합이|변화구 하나만/;
 const bad=t=>G2.test(t)||(/오늘/.test(t)&&!/오늘 (야구 커뮤|댓글|기사|발표|오피셜|은|은 마셔)/.test(t));
 const _cC2=comments;comments=function(tone,x){let out=_cC2(tone,x);try{if(!Array.isArray(out)||!CT2.includes(tone))return out;out=out.filter(c=>!(c&&bad(String(c.t||''))));out.forEach(c=>{if(c&&Array.isArray(c.re))c.re=c.re.filter(r=>!bad(String(r&&r.t||'')))})}catch(e){}return out}}

/* 특성(확률형 TR) 효과 전체 아주 살짝 하향: 확률 가산 ×0.9 · 배수형은 증가분 ×0.9 · 설명 숫자도 맞춤 */
const TR_SCALE=.9;
try{TR.forEach(t=>{if(!t||!t.a||typeof t.d!=='string')return;t.d=t.d.replace(/([+−-])(\d+(?:\.\d+)?)(%p?)/g,(m,sg,n,u)=>{const v=Math.round(parseFloat(n)*TR_SCALE*10)/10;return sg+(v%1?v.toFixed(1):String(v))+u})})}catch(e){}
{const _taS=trAdj;trAdj=function(type,ctx,season){const o=_taS(type,ctx,season);try{o.hit*=TR_SCALE;o.k*=TR_SCALE;o.bb*=TR_SCALE;o.gap*=TR_SCALE;o.hr=1+(o.hr-1)*TR_SCALE}catch(e){}return o}}

/* 30세부터 훈련 효과 서서히 감소: 오른 만큼에 (1−0.02×1.25^(나이−30)) 적용 · 최소 ×0.7 */
{const _tmA=trainMonth;trainMonth=function(rep){const a=(()=>{try{return age()}catch(e){return 0}})();if(a<30||!ME)return _tmA(rep);
  const r0={...ME.r},p0=ME.pt?{...ME.pt}:null;const out=_tmA(rep);try{const f=Math.max(.7,1-.02*Math.pow(1.25,a-30));
  for(const k in r0){if(typeof ME.r[k]==='number'&&typeof r0[k]==='number'&&ME.r[k]>r0[k])ME.r[k]=r0[k]+(ME.r[k]-r0[k])*f}
  if(p0&&ME.pt)for(const k in p0){if(typeof ME.pt[k]==='number'&&typeof p0[k]==='number'&&ME.pt[k]>p0[k]&&p0[k]>0)ME.pt[k]=p0[k]+(ME.pt[k]-p0[k])*f}}catch(e){}return out}}

/* 시리즈가 끝난 가을야구 기사(우승 확정·탈락): "내일/다음 경기" 류 댓글·대댓글 제거 */
{const NX=/내일|다음 경기|다음 판|다음 등판|다음 타석/;const _cNX=comments;comments=function(tone,x){let out=_cNX(tone,x);try{if(!Array.isArray(out)||!x||!x.ps||x.intl)return out;const end=(x.clinch&&x.win)||(x.elim&&!x.win)||(!x.win&&/지면 탈락|마지막 승부/.test(String(x.sub||'')));if(!end)return out;
  out=out.filter(c=>!(c&&NX.test(String(c.t||''))));out.forEach(c=>{if(c&&Array.isArray(c.re))c.re=c.re.filter(r=>!NX.test(String(r&&r.t||'')))})}catch(e){}return out}}

/* 불펜 멀티이닝: 시즌 ERA 2.5 이하 + 체력 좋은 불펜만 가끔 더 길게 (설명 노노) */
function mlBon(){try{if(!isP()||ME.pos!=='RP')return 0;const e=relEra(),s=DV(E('sta'));if(e==null||e>=5)return 0;const f=cl((s-40)/40,0,1.2);return cl(((5-e)*.03+.02)*f,0,.16)}catch(e){return 0}}
function mlEl(){try{if(!isP()||ME.pos!=='RP')return false;const e=relEra(),s=DV(E('sta'));return e!=null&&e<=2.5&&s>=60}catch(e){return false}}
function rp3(){try{return R()<(mlEl()?.22:.05)}catch(e){return false}}

/* KBO 한정 구속 보너스 아주 살짝 (설명 노노) */
function kboV(){try{if(!isP()||S.stage!=='pro'||!S.pro||S.pro.league!=='KBO')return 0;return Math.max(0,Math.min(1,(DV(eff('velo'))-60)*.025))}catch(e){return 0}}

/* 중간계투 등판 상황: 필승조급은 접전, 패전조(mop)는 점수 차 큰 경기 위주 (7회엔 무조건) */
function mrOk(l,late){try{if(late)return true;const a=Math.abs(l);return S.mopNow?a>=4:a<=5}catch(e){return true}}

