function retPosK(){try{if(!isP())return ME.pos;return hofMainRole()==='SP'?'SP':'RP'}catch(e){return ME.pos==='SP'?'SP':'RP'}}
function retPosN(){try{return POS[retPosK()]||POS[ME.pos]}catch(e){return POS[ME.pos]}}

/* ===== 반기 도중 끊기: 부상·감독 면담(부진/보직)·2군행 통보·국제대회 출국이 생기면 그 달에서 멈추고 바로 보여준 뒤, 처리하면 남은 달을 이어서 진행 ===== */
function midHit(q){try{if(!q)return false;if(q.type==='intlshow')return true;const t=String(q.title||'');return !q.type&&(/감독 면담 — |2군행 통보|트리플A행 통보|🚑|인대 손상|병역 특례|첫 보직 면담|첫 스프링캠프 — 보직|감독의 부탁 — |📞 콜업/.test(t)||t.startsWith('😮‍💨 '))}catch(e){return false}} /* v841e: 시즌 중 부탁·콜업·선수단 이벤트는 그 달 바로 (후반기에 쌓였다가 11월 비시즌에 뜨던 것) */
function midStop(q0){try{if(S.stage!=='pro'&&S.stage!=='hs'&&S.stage!=='univ')return false;return S.queue.slice(q0).some(midHit)}catch(e){return false}}
{const _advMid=advance;advance=function(){try{return _advMid.apply(this,arguments)}catch(e){if(e&&e.__mid){try{save()}catch(_){}return}throw e}}}

/* ===== 부진 처리 공통: 한 반기에 면담·강등 통보는 하나만 · 보직 변경(패전조/대타) 선택지 · 2군행 약점 보완(1.5 나눔) · 타자 극심한 부진은 바로 2군 ===== */
function slH(){return S.y+'-'+S.phase}
function slOK(){try{const now=S.y*12+S.m;if(S._slH===slH())return false;if((S.kboDown&&now<S.kboDown.until)||(S.mlbDown&&now<S.mlbDown.until)||(S.mlbReset&&now<S.mlbReset.until)||(S.slRole&&now<S.slRole.until))return false;
  return !(S.queue||[]).some(q=>/감독 면담 — |행 통보/.test(q.title||''))}catch(e){return true}}
function slSet(){S._slH=slH()}
function slRoleCh(){return isP()?{t:'불펜 패전조로 잠시 내려간다',s:'두 달 패전조 · 성장 포인트↑ 체력↑ · 인기↓ · 홀드·세이브 없음',act:'slRole',arg:{}}:{t:'대타·백업으로 한발 물러선다',s:'두 달 대타·백업 · 성장 포인트↑ 피로↓ · 인기↓',act:'slRole',arg:{}}}
