/* 타순: 발 느리면 1·2번 안 감(1번 주력 60+, 2번 55+, 3번 45+) · 느린 타자는 5번 뒤가 기본, 홈런·타격 좋을수록 4번 쪽 */
batOrder=function(L){const c=E('con'),p=E('pow'),s=E('spd'),e=E('eye'),t=c*.36+p*.3+e*.2+s*.14-L,sp=DV(s);
  const prof={1:s*.45+e*.3+c*.25,2:c*.5+e*.3+s*.2,3:c*.5+p*.5,4:p*.75+c*.25,5:p*.6+c*.4,6:(c+p)/2,7:(c+s)/2,8:c*.6+e*.4,9:s*.5+c*.5};
  let cand=sp>=55?(t>=5?[4,3,1,2,5]:t>=1?[1,2,5,3,6]:t>=-3?[6,2,7,5]:[7,8,9]):(t>=5?[4,3,5]:t>=2?[4,5,3,6]:t>=0?[5,6,4]:t>=-3?[6,7,5]:[7,8,9]);
  cand=cand.filter(o=>!(o===1&&sp<60)&&!(o===2&&sp<55)&&!(o===3&&sp<45));if(t<-3)cand=t<-5?[9,8]:[8,9,7]; /* v792: 타격 약하면 발 느려도 9번 */if(!cand.length)cand=[7,8];
  let best=cand[0],bv=-1e9;cand.forEach((o,i)=>{const v=prof[o]-i*.6;if(v>bv){bv=v;best=o}});return best};

