function ringsNow841(){try{return leagueRings()+((S.awards||[]).some(z=>z&&z.y===S.y&&/^(한국시리즈|월드시리즈) 우승$/.test(String(z.n||'')))?0:1)}catch(e){return leagueRings()}}
