  const isRingArt=tone==='ring'||tone==='ws'||(x.clinch&&x.win&&/한국시리즈|월드시리즈/.test(String(x.title||'')));
  /* ① */
  if(!leagueRings()&&!isRingArt){out=out.filter(c=>!RINGY.test(String((c&&c.t)||'')));out.forEach(c=>{if(c&&Array.isArray(c.re))c.re=c.re.filter(q=>!RINGY.test(String((q&&q.t)||'')))})}
  const kbo=S.pro.league==='KBO',my=S.pro.team,ps=!!(x.ps&&!x.intl),title=String(x.title||'');
