function retFanBest(skip){try{const ey=(S.ended&&S.ended.y)||S.y,seen=new Set(skip||[]),pool=[];
  (S.arts||[]).filter(a=>a&&a.y>=ey-1&&(/^(retire|hof|legend)$/.test(String(a.tone||''))||/은퇴|영구결번|명예의 전당/.test(String(a.head||'')))).forEach(a=>(a.cm||[]).forEach(c=>{if(!c||!c.t)return;const t=String(typeof nmFull==='function'?nmFull(c.t):c.t).trim();if(t.length<8||seen.has(t))return;seen.add(t);pool.push({nk:String(c.nk||'').replace(/^@/,''),t,up:+c.up||0})}));
  if(pool.length<3)return null;
  const B=[['thanks',/고마|덕분|행복|수고|감사/],['memory',/엊그제|처음|떡잎|드래프트|그때|데뷔|신인/],['stat',/\d{2,}|통산|WAR|안타 자판기|홈런|세이브|탈삼진/],['tears',/오열|울었|울컥|눈물|청춘|누구 보고|한 시대|상상/],['family',/아들|딸|아빠|엄마|가족|자식/],['future',/돌아와|두 번째|제2의|감독|코치|해설|꽃길/]];
  const sc=c=>Math.log10(1+c.up)+(B.some(b=>b[1].test(c.t))?2:0)+(c.t.length>=12&&c.t.length<=48?1:0)+R()*.6;
  pool.forEach(c=>c.s=sc(c));const pick5=[],used=new Set();
  for(const [k,re] of B.slice().sort(()=>R()-.5)){if(pick5.length>=5)break;const c=pool.filter(z=>!used.has(z)&&re.test(z.t)).sort((a,b)=>b.s-a.s)[0];if(c){used.add(c);pick5.push(c)}}
  pool.filter(z=>!used.has(z)).sort((a,b)=>b.s-a.s).forEach(z=>{if(pick5.length<5){used.add(z);pick5.push(z)}});
  return pick5.sort((a,b)=>b.up-a.up)}catch(e){return null}}
{const _rsF=recapSlides;recapSlides=function(){const sl=_rsF.apply(this,arguments);try{if(!S||!S.ended)return sl;const fi=sl.findIndex(s=>s&&s.ey==='팬들의 한마디');
  const skip=fi>=0&&Array.isArray(sl[fi].quotes)?sl[fi].quotes.map(q=>String(q&&q[1]||'')):[];
  if(!S._fanBest||S._fanBest.y!==(S.ended.y||S.y)){const L=retFanBest(skip);S._fanBest=L?{y:S.ended.y||S.y,L}:null}
  const L=S._fanBest&&S._fanBest.L;if(!L||L.length<3)return sl;
  const s={th:'purple',ey:'마지막 인사 · 댓글 BEST 5',quotes:L.map(c=>[`${c.nk} · ♥ ${kfmt(c.up)}`,c.t])};
  let at=fi>=0?fi+1:sl.findIndex(x=>x&&x.last);if(at<0)at=sl.length;sl.splice(at,0,s)}catch(e){}return sl}}

/* v651: 은퇴 투어 — 구단이 '딱 은퇴할 시기'라고 볼 때 전반기 활약을 보고 제안 (후반기 시작 시)
   기준 나이 40세 (메이저에서 잘하고 돌아온 선수는 41세, 성적 영향도 덜 받음 → 대개 41~42세에 제안)
   전반기 부진·퓨처스·계약 마지막 해면 앞당겨지고, 전반기에 잘하면 미뤄짐. 거절하면 다음 해 전반기 끝에 또 비슷하게 옴.
   수락 → 후반기 은퇴투어 → 시즌 끝나고 은퇴 */
/* 은퇴투어 자격: KBO에서 5시즌 이상 + (KBO WAR + 메이저 WAR×1.3) 70 이상 · 메이저리그엔 은퇴투어 없음 */
function tourElig(){try{if(!S||!S.pro||S.pro.league!=='KBO')return null;let k=0,m=0;const ky=new Set();S.rows.forEach(r=>{if(r.lv==='KBO'){k+=rowWAR(r);if((r.b&&r.b.PA)||(r.p&&r.p.outs))ky.add(r.y)}else if(r.lv==='MLB')m+=rowWAR(r)});
  const tot=k+1.3*m;return ky.size>=5&&tot>=70?/* v842j: 은퇴투어 자격(KBO WAR+메이저×1.3)은 노화 뒤에도 자격자 비율이 그대로라(33.8%→32.9%) 70 유지 */{kbo:k,mlb:m,tot,yrs:ky.size}:null}catch(e){return null}}
function tourChance(){try{if(!S||S.stage!=='pro'||!S.pro||!ME||S.ended)return 0;const v=vetInfo();if(!v||v.a<37)return 0;
  const el=tourElig();if(!el)return 0;
  const mlbW=el.mlb,mlbBack=mlbW>=12;
  /* 기준 나이에 전반기 평범 ≈60% · 부진 ≈90% · 잘하면 10~15% / 1살 어리면 평범 ≈20% · 부진 ≈60% */
  const T=mlbBack?40:39,good=v.pace==null?0:s01((v.pace-3)/2),perfW=mlbBack?.6:1;/* v842s: 노화 뒤 40살까지 뛰는 선수가 줄어서(61%→35%) 기준 나이 한 살 당김 (반 살로는 13.9%라 부족) */
  const z=(v.a-T)+perfW*(1.6*(v.dec-.35)-1.2*good)+(v.last?.3:0)+(v.fut?.4:0)+((S._tourNo||0)>0?.5:0);
  return s01(v.a-36.5)*sg(z/.55+.4)}catch(e){return 0}}
