  try{const tt=yearTot(S.y,['KBO','MLB']),adj=OPSADJ[ME.pos]||0;if(f.P){const e=tt.p.outs?tt.p.R*27/tt.p.outs*.92:0,he=parseFloat(x.era);if(e<4.0||(half&&isFinite(he)&&he<3.8))return out}
    else{const b=tt.b,o=b.AB?(b.H+b.BB)/(b.AB+b.BB)+(b.H+b.D+2*b.T+3*b.HR)/b.AB:1,ho=parseFloat(x.ops);if(o>=.72+adj||(half&&isFinite(ho)&&ho>=.72+adj))return out}}catch(e){}
  const k=S.y+'-'+S.phase;if(S._flK===k)return out;
  const badGame=x.gPA!=null?((x.gH||0)===0&&(x.gPA||0)>=3):x.ipO!=null?((x.ra||0)>=3):false;
  const p=half?.55:badGame?.15:0;if(R()>=p)return out;S._flK=k;
  const gn=giv(ME.name),old=f.a>=36,L=old?[`작년이 마지막 불꽃이었나…`,`에이징 커브 시작인가 ㅠ`,`작년 생각하면 아쉽다 나이는 못 속이나`,`작년 같은 ${gn} 다시 볼 수 있을까`]
    :[`작년은 플루크였나…`,`작년 성적 보고 기대했는데 올해 왜 이럼`,`이렇게 하다 반짝 사라지는 애들 많다`,`상대 팀들이 ${gn} 분석 끝낸 듯`,`작년이 커리어하이로 남을 각인데`,`한 시즌 반짝은 누구나 한다 두 시즌은 해야 진짜지`].concat(f.yr===2?['2년차 징크스 제대로 왔네']:[]);
  let t=josaFix(pick(L));if(seenHas(t))t=josaFix(pick(L));if(seenHas(t))return out;seenAdd(t);
  const pro=['아직 판단은 이르다','한 시즌만 더 보자','작년도 운은 아니었다','폼 찾으면 돌아온다'],con=['ㄹㅇ 반짝 느낌','이게 진짜 실력일 수도','작년엔 운이 좋았지',S.pro&&S.pro.league==='MLB'?'이러다 마이너 간다':'이러다 2군 간다'];
